window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id": "yy-17182", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "只有新时代发展的宏伟蓝图真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：", "options": ["描绘", "擘画", "勾画", "规划"], "answer": 1, "explanation": "「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选B。"}, {"id": "yy-17183", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "各地区各部门要拿出真招实招，______公共服务水平，确保各项部署落地生根。填入画横线处最恰当的是：", "options": ["增强", "提升", "拔高", "提高"], "answer": 1, "explanation": "「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选B。"}, {"id": "yy-17188", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "各级政府要持续______就业促进机制，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：", "options": ["健全", "搭建", "构建", "完善"], "answer": 0, "explanation": "「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选A。"}, {"id": "yy-17194", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "要坚持问题导向，______现代化建设的宏伟篇章，切实解决群众急难愁盼问题。填入画横线处最恰当的是：", "options": ["规划", "擘画", "描绘", "勾画"], "answer": 1, "explanation": "「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选B。"}, {"id": "yy-17200", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "当前正值关键时期，______高质量发展的生态底色刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：", "options": ["加深", "筑牢", "厚植", "培植"], "answer": 2, "explanation": "「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选C。"}, {"id": "yy-17207", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "越是任务艰巨，越要______各方合力，确保方向不偏、力度不减。填入画横线处最恰当的是：", "options": ["凝聚", "集中", "汇聚", "聚集"], "answer": 0, "explanation": "「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选A。"}, {"id": "yy-17208", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "要坚持问题导向，______制造业高质量发展，切实解决群众急难愁盼问题。填入画横线处最恰当的是：", "options": ["赋能", "助力", "赋权", "加持"], "answer": 0, "explanation": "「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选A。"}, {"id": "yy-17209", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "各级政府要持续______政策效应，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：", "options": ["发挥", "散发", "释放", "爆发"], "answer": 2, "explanation": "「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选C。"}, {"id": "yy-17211", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "要坚持问题导向，______经济社会发展全过程，切实解决群众急难愁盼问题。填入画横线处最恰当的是：", "options": ["贯穿", "经过", "贯串", "穿过"], "answer": 0, "explanation": "「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选A。"}, {"id": "yy-17213", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "要在______就业促进机制上下更大功夫，让发展成果更多惠及全体人民。填入画横线处最恰当的是：", "options": ["构建", "完善", "搭建", "健全"], "answer": 3, "explanation": "「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选D。"}, {"id": "yy-17215", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "只有政策效应真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：", "options": ["爆发", "释放", "发挥", "散发"], "answer": 1, "explanation": "「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选B。"}, {"id": "yy-17219", "module": "yanyu", "diff": 3, "exam": "医疗编", "prompt": "新征程上，要继续______现代化建设全局，以实干实绩回应人民期盼。填入画横线处最恰当的是：", "options": ["贯串", "经过", "贯穿", "穿过"], "answer": 2, "explanation": "「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选C。"}, {"id": "yy-17221", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "新征程上，要继续______新兴产业，以实干实绩回应人民期盼。填入画横线处最恰当的是：", "options": ["培育", "孕育", "培植", "培养"], "answer": 0, "explanation": "「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选A。"}, {"id": "yy-17502", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "各级政府要持续______矛盾调解体系，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：", "options": ["构建", "搭建", "健全", "完善"], "answer": 2, "explanation": "「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选C。"}, {"id": "yy-17503", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "实践证明，______共识是推动高质量发展的关键一招。填入画横线处最恰当的是：", "options": ["聚集", "凝聚", "汇聚", "集中"], "answer": 1, "explanation": "「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选B。"}, {"id": "yy-17506", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "要坚持问题导向，______腐败蔓延的态势，切实解决群众急难愁盼问题。填入画横线处最恰当的是：", "options": ["控制", "遏止", "遏制", "制止"], "answer": 2, "explanation": "「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选C。"}, {"id": "yy-17507", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "面对新形势新任务，必须______东西部协作，牢牢把握发展主动权。填入画横线处最恰当的是：", "options": ["推进", "深化", "深入", "加强"], "answer": 1, "explanation": "「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选B。"}, {"id": "yy-17509", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "面对新形势新任务，必须______企业主体责任，牢牢把握发展主动权。填入画横线处最恰当的是：", "options": ["落实", "压实", "压紧", "强化"], "answer": 1, "explanation": "「压实」与「责任」搭配，强调责任层层落实到位；「落实」为通用动词；「压紧」常作「压紧压实」；「强化」不如「压实」精准体现层级传导。故选B。"}, {"id": "yy-17510", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "各级政府要持续______发展优势，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：", "options": ["筑牢", "厚植", "加深", "培植"], "answer": 1, "explanation": "「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选B。"}, {"id": "yy-17513", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "当前正值关键时期，______实体经济根基刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：", "options": ["厚植", "加深", "筑牢", "培植"], "answer": 0, "explanation": "「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选A。"}, {"id": "yy-17514", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "越是任务艰巨，越要______中小企业发展，确保方向不偏、力度不减。填入画横线处最恰当的是：", "options": ["助力", "赋权", "赋能", "加持"], "answer": 2, "explanation": "「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选C。"}, {"id": "yy-17515", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "回顾这些年走过的路，______民生短板始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：", "options": ["填补", "弥补", "补足", "补齐"], "answer": 3, "explanation": "「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选D。"}, {"id": "yy-17518", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "要在______数字化底座上下更大功夫，让发展成果更多惠及全体人民。填入画横线处最恰当的是：", "options": ["夯实", "巩固", "筑牢", "打牢"], "answer": 0, "explanation": "「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。"}, {"id": "yy-17520", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "越是任务艰巨，越要______风险意识，确保方向不偏、力度不减。填入画横线处最恰当的是：", "options": ["深化", "加强", "增强", "强化"], "answer": 3, "explanation": "「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选D。"}, {"id": "yy-17522", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "要在______放管服改革上下更大功夫，让发展成果更多惠及全体人民。填入画横线处最恰当的是：", "options": ["加强", "推进", "深入", "深化"], "answer": 3, "explanation": "「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选D。"}, {"id": "yy-17524", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "实践证明，______现代化建设的宏伟篇章是推动高质量发展的关键一招。填入画横线处最恰当的是：", "options": ["描绘", "擘画", "规划", "勾画"], "answer": 1, "explanation": "「擘画」指筹划布置，多用于宏观蓝图，书面色彩浓；「描绘」「勾画」偏具体画面；「规划」语体色彩不足。故选B。"}, {"id": "yy-17535", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "实践证明，______建设农业强国的目标是推动高质量发展的关键一招。填入画横线处最恰当的是：", "options": ["瞄准", "盯住", "锁定", "锚定"], "answer": 3, "explanation": "「锚定」比喻像锚一样固定住目标，多用于宏观战略语境；「锁定」「瞄准」「盯住」语体偏口语，庄重色彩不足。故选D。"}, {"id": "yy-17536", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "实践证明，______经营主体信心是推动高质量发展的关键一招。填入画横线处最恰当的是：", "options": ["调动", "引发", "点燃", "激发"], "answer": 3, "explanation": "「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。"}, {"id": "yy-17538", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "新征程上，要继续______不发生系统性风险的底线，以实干实绩回应人民期盼。填入画横线处最恰当的是：", "options": ["守牢", "守住", "把牢", "防住"], "answer": 0, "explanation": "「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选A。"}, {"id": "yy-17539", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "面对新形势新任务，必须______发展根基，牢牢把握发展主动权。填入画横线处最恰当的是：", "options": ["夯实", "打牢", "筑牢", "巩固"], "answer": 0, "explanation": "「夯实」本义为砸实地基，引申为使稳固，与「基础、根基」搭配；「筑牢」与「防线」搭配；「打牢」语体稍口语；「巩固」侧重使已有的更牢固。故选A。"}, {"id": "yy-17540", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "当前正值关键时期，______耕地保护红线刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：", "options": ["守住", "把牢", "守牢", "防住"], "answer": 2, "explanation": "「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。"}, {"id": "yy-17545", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "各级政府要持续______安全屏障，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：", "options": ["构建", "筑造", "筑牢", "夯实"], "answer": 2, "explanation": "「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选C。"}, {"id": "yy-17547", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "各级政府要持续______科技成果转化路径，不断增强群众的获得感、幸福感、安全感。填入画横线处最恰当的是：", "options": ["打通", "疏通", "畅通", "开拓"], "answer": 2, "explanation": "「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。"}, {"id": "yy-17548", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "实践证明，______乡村振兴始终是推动高质量发展的关键一招。填入画横线处最恰当的是：", "options": ["贯穿", "贯串", "经过", "穿过"], "answer": 0, "explanation": "「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选A。"}, {"id": "yy-17549", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "面对新形势新任务，必须______发展规律，牢牢把握发展主动权。填入画横线处最恰当的是：", "options": ["把玩", "把守", "把握", "把持"], "answer": 2, "explanation": "「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选C。"}, {"id": "yy-17552", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "当前正值关键时期，______市场变化刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：", "options": ["把守", "把握", "把持", "把玩"], "answer": 1, "explanation": "「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选B。"}, {"id": "yy-17554", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "越是任务艰巨，越要______市场变化，确保方向不偏、力度不减。填入画横线处最恰当的是：", "options": ["把握", "把持", "把守", "把玩"], "answer": 0, "explanation": "「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选A。"}, {"id": "yy-17558", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "当前正值关键时期，______生态恶化的趋势刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：", "options": ["遏止", "控制", "制止", "遏制"], "answer": 3, "explanation": "「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选D。"}, {"id": "yy-17561", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "要在______现代化建设全局上下更大功夫，让发展成果更多惠及全体人民。填入画横线处最恰当的是：", "options": ["贯串", "经过", "穿过", "贯穿"], "answer": 3, "explanation": "「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选D。"}, {"id": "yy-17566", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "新征程上，要继续______政企沟通机制，以实干实绩回应人民期盼。填入画横线处最恰当的是：", "options": ["开拓", "疏通", "畅通", "打通"], "answer": 2, "explanation": "「畅通」强调使通畅无阻，与「渠道」为固定搭配；「打通」侧重突破障碍；「疏通」多用于管道或疏导矛盾；「开拓」指开辟新领域。故选C。"}, {"id": "yy-17570", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "下一步，将______民意反映渠道，推动各项工作再上新台阶。填入画横线处最恰当的是：", "options": ["拓宽", "延伸", "扩大", "开拓"], "answer": 0, "explanation": "「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选A。"}, {"id": "yy-17572", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "只有东西部协作真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：", "options": ["加强", "深入", "推进", "深化"], "answer": 3, "explanation": "「深化」指向更深阶段发展，与「改革」为固定搭配；「深入」多作形容词或「深入调查」；「加强」「推进」语义宽泛。故选D。"}, {"id": "yy-17575", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "要坚持问题导向，______消费潜力，切实解决群众急难愁盼问题。填入画横线处最恰当的是：", "options": ["散发", "发挥", "释放", "爆发"], "answer": 2, "explanation": "「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选C。"}, {"id": "yy-17576", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "实践证明，______安全屏障是推动高质量发展的关键一招。填入画横线处最恰当的是：", "options": ["构建", "筑牢", "筑造", "夯实"], "answer": 1, "explanation": "「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选B。"}, {"id": "yy-17577", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "新征程上，要继续______群众获得感，以实干实绩回应人民期盼。填入画横线处最恰当的是：", "options": ["提高", "拔高", "增强", "提升"], "answer": 3, "explanation": "「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选D。"}, {"id": "yy-17579", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "要坚持问题导向，______民意直达渠道，切实解决群众急难愁盼问题。填入画横线处最恰当的是：", "options": ["打通", "畅通", "开辟", "贯通"], "answer": 1, "explanation": "「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选B。"}, {"id": "yy-17582", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "实践证明，______安全稳定底线是推动高质量发展的关键一招。填入画横线处最恰当的是：", "options": ["防住", "守牢", "把牢", "守住"], "answer": 1, "explanation": "「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选B。"}, {"id": "yy-17587", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "实践证明，______时代脉搏是推动高质量发展的关键一招。填入画横线处最恰当的是：", "options": ["把玩", "把握", "把守", "把持"], "answer": 1, "explanation": "「把握」与抽象事物（特点、规律、机遇）搭配；「把守」指守卫关口，「把持」含贬义指独揽，「把玩」指赏玩物品。故选B。"}, {"id": "yy-17589", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "回顾这些年走过的路，______数据要素价值始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：", "options": ["释放", "发挥", "爆发", "散发"], "answer": 0, "explanation": "「释放」与「潜力、红利、活力」搭配；「散发」指分散发出；「发挥」与「作用」搭配；「爆发」指突然发作。故选A。"}, {"id": "yy-17590", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "回顾这些年走过的路，______经济社会发展全过程始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：", "options": ["贯串", "经过", "穿过", "贯穿"], "answer": 3, "explanation": "「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选D。"}, {"id": "yy-17595", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "当前正值关键时期，______生态保护红线刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：", "options": ["把牢", "守住", "守牢", "防住"], "answer": 2, "explanation": "「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。"}, {"id": "yy-17599", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "面对新形势新任务，必须______思想防线，牢牢把握发展主动权。填入画横线处最恰当的是：", "options": ["构建", "夯实", "筑牢", "筑造"], "answer": 2, "explanation": "「筑牢」与「防线」为固定搭配，强调使牢固；「筑造」指建造实体；「构建」侧重搭建体系；「夯实」多与「基础」搭配。故选C。"}, {"id": "yy-17601", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "只有安全稳定底线真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：", "options": ["把牢", "防住", "守牢", "守住"], "answer": 2, "explanation": "「守牢」与「底线」搭配，强调牢牢守住；「守住」程度稍弱；「把牢」多与「关口」搭配；「防住」为口语。故选C。"}, {"id": "yy-17603", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "越是任务艰巨，越要______民意直达渠道，确保方向不偏、力度不减。填入画横线处最恰当的是：", "options": ["畅通", "开辟", "贯通", "打通"], "answer": 0, "explanation": "「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选A。"}, {"id": "yy-17607", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "面对新形势新任务，必须______传统产业转型升级，牢牢把握发展主动权。填入画横线处最恰当的是：", "options": ["赋权", "赋能", "加持", "助力"], "answer": 1, "explanation": "「赋能」指赋予能力，是数字经济语境的规范表述；「赋权」指赋予权力；「加持」为口语化外来词；「助力」语义宽泛。故选B。"}, {"id": "yy-17611", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "只有矛盾调解体系真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：", "options": ["完善", "健全", "搭建", "构建"], "answer": 1, "explanation": "「健全」强调使完备无缺；「完善」指补足短板；「构建」「搭建」侧重从无到有搭建。故选B。"}, {"id": "yy-17616", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "下一步，将______专精特新企业，推动各项工作再上新台阶。填入画横线处最恰当的是：", "options": ["培植", "培养", "培育", "孕育"], "answer": 2, "explanation": "「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选C。"}, {"id": "yy-17618", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "越是任务艰巨，越要______公共卫生体系短板，确保方向不偏、力度不减。填入画横线处最恰当的是：", "options": ["弥补", "补足", "补齐", "填补"], "answer": 2, "explanation": "「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选C。"}, {"id": "yy-17623", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "当前正值关键时期，______各方合力刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：", "options": ["汇聚", "凝聚", "集中", "聚集"], "answer": 1, "explanation": "「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选B。"}, {"id": "yy-17625", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "当前正值关键时期，______视野和思路刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：", "options": ["扩大", "拓宽", "开拓", "延伸"], "answer": 1, "explanation": "「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选B。"}, {"id": "yy-17626", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "要在______覆盖范围上下更大功夫，让发展成果更多惠及全体人民。填入画横线处最恰当的是：", "options": ["扩大", "延伸", "开拓", "拓宽"], "answer": 3, "explanation": "「拓宽」与「渠道、门路、视野」搭配；「开拓」指开辟新领域；「扩大」多与「规模、范围」搭配；「延伸」侧重长度延长。故选D。"}, {"id": "yy-17629", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "面对新形势新任务，必须______房价过快上涨的势头，牢牢把握发展主动权。填入画横线处最恰当的是：", "options": ["遏止", "控制", "制止", "遏制"], "answer": 3, "explanation": "「遏制」强调压制住势头、多与「势头/态势」搭配；「遏止」侧重使之停止，多用于具体行为；「控制」「制止」语义宽泛。故选D。"}, {"id": "yy-17632", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "新征程上，要继续______服务空白，以实干实绩回应人民期盼。填入画横线处最恰当的是：", "options": ["弥补", "填补", "补齐", "补足"], "answer": 2, "explanation": "「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选C。"}, {"id": "yy-17633", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "要坚持问题导向，______各类资源配置，切实解决群众急难愁盼问题。填入画横线处最恰当的是：", "options": ["统率", "统筹", "兼顾", "协调"], "answer": 1, "explanation": "「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选B。"}, {"id": "yy-17634", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "要坚持问题导向，______营商环境，切实解决群众急难愁盼问题。填入画横线处最恰当的是：", "options": ["优化", "调整", "改进", "改善"], "answer": 0, "explanation": "「优化」指加以改变使其优良，与「环境、结构」搭配规范；「改善」多与「条件、生活」搭配；「改进」多与「方法、工作」搭配；「调整」不含变优之义。故选A。"}, {"id": "yy-17636", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "回顾这些年走过的路，______生产生活生态始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：", "options": ["统筹", "协调", "统率", "兼顾"], "answer": 0, "explanation": "「统筹」指全面筹划、统一安排，与「推进」搭配且强调全局性；「统率」指率领；「兼顾」只强调同时照顾；「协调」侧重配合关系。故选A。"}, {"id": "yy-17638", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "新征程上，要继续______改革开放各领域，以实干实绩回应人民期盼。填入画横线处最恰当的是：", "options": ["穿过", "贯串", "经过", "贯穿"], "answer": 3, "explanation": "「贯穿」指从头到尾通贯，与「全过程」搭配规范；「穿过」「经过」仅指空间或时间经过，不含通贯始终之义。故选D。"}, {"id": "yy-17641", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "要在______创新创造潜能上下更大功夫，让发展成果更多惠及全体人民。填入画横线处最恰当的是：", "options": ["引发", "点燃", "调动", "激发"], "answer": 3, "explanation": "「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。"}, {"id": "yy-17643", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "回顾这些年走过的路，______资源、服务、管理始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：", "options": ["下沉", "下探", "下潜", "下坠"], "answer": 0, "explanation": "「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选A。"}, {"id": "yy-17645", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "回顾这些年走过的路，______群众获得感始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：", "options": ["增强", "提升", "提高", "拔高"], "answer": 1, "explanation": "「提升」与「效能、水平」搭配规范；「提高」语义相近但「提升」更书面；「增强」多与「能力、意识」搭配；「拔高」含贬义。故选B。"}, {"id": "yy-17646", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "要在______内生动力上下更大功夫，让发展成果更多惠及全体人民。填入画横线处最恰当的是：", "options": ["点燃", "引发", "调动", "激发"], "answer": 3, "explanation": "「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选D。"}, {"id": "yy-17649", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "越是任务艰巨，越要______爱国情怀，确保方向不偏、力度不减。填入画横线处最恰当的是：", "options": ["厚植", "加深", "培植", "筑牢"], "answer": 0, "explanation": "「厚植」指深厚培育，与「优势、底色、根基」搭配；「培植」多用于培育动植物或扶植势力；「加深」与「底色」搭配不当。故选A。"}, {"id": "yy-17650", "module": "yanyu", "diff": 3, "exam": "医疗编", "prompt": "当前正值关键时期，______意志刻不容缓，必须抓紧抓实抓出成效。填入画横线处最恰当的是：", "options": ["锤炼", "砥砺", "锻炼", "磨砺"], "answer": 1, "explanation": "「砥砺」本义为磨刀石，引申为磨炼，与「意志」搭配且语体庄重；「磨砺」与之近义但「砥砺」更常用于「砥砺前行、砥砺意志」。故选B。"}, {"id": "yy-17652", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "只有科技成果转化通道真正______到基层，才能让政策在「最后一公里」落地见效。填入画横线处最恰当的是：", "options": ["打通", "开辟", "畅通", "贯通"], "answer": 2, "explanation": "「畅通」强调使通畅无阻，与「渠道、通道」搭配；「打通」侧重突破障碍；「贯通」指连接相通；「开辟」指新开路径。故选C。"}, {"id": "yy-17654", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "下一步，将______各方合力，推动各项工作再上新台阶。填入画横线处最恰当的是：", "options": ["汇聚", "凝聚", "聚集", "集中"], "answer": 1, "explanation": "「凝聚」多与「共识、人心、力量」搭配，强调由分散到统一；「聚集」侧重物理集合；「集中」侧重把分散的集中起来。故选B。"}, {"id": "yy-17656", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "要坚持问题导向，______责任担当，切实解决群众急难愁盼问题。填入画横线处最恰当的是：", "options": ["加强", "深化", "强化", "增强"], "answer": 2, "explanation": "「强化」与「意识、思维」搭配，强调使之更牢固；「增强」语义相近但搭配习惯不同；「加强」为通用动词；「深化」指向深处发展。故选C。"}, {"id": "yy-17657", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "新征程上，要继续______制度漏洞，以实干实绩回应人民期盼。填入画横线处最恰当的是：", "options": ["弥补", "补齐", "补足", "填补"], "answer": 1, "explanation": "「补齐」与「短板」为固定搭配，强调使达到应有水平；「补足」多与「差额」搭配；「填补」多与「空白」搭配；「弥补」多与「损失」搭配。故选B。"}, {"id": "yy-17659", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "面对新形势新任务，必须______优质医疗资源，牢牢把握发展主动权。填入画横线处最恰当的是：", "options": ["下潜", "下探", "下沉", "下坠"], "answer": 2, "explanation": "「下沉」指治理资源向基层倾斜，是规范表述；「下潜」指潜水，「下探」多指价格或行动试探，「下坠」指物体坠落。故选C。"}, {"id": "yy-17672", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "各地区各部门要拿出真招实招，______消费新增长点，确保各项部署落地生根。填入画横线处最恰当的是：", "options": ["培育", "孕育", "培植", "培养"], "answer": 0, "explanation": "「培育」与「产业、企业、市场」搭配；「培养」对象为人或能力；「培植」多用于动植物或含贬义；「孕育」强调正在形成。故选A。"}, {"id": "yy-17676", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "回顾这些年走过的路，______市场主体活力始终是我们攻坚克难的重要法宝。填入画横线处最恰当的是：", "options": ["引发", "激发", "点燃", "调动"], "answer": 1, "explanation": "「激发」与「活力、热情、潜能」为固定搭配；「引发」多与「关注、争议」搭配；「点燃」为比喻用法；「调动」多与「积极性」搭配。故选B。"}, {"id": "yy-18001", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "岁末年初，营商环境就是生产力，工程师让企业成长有沃土。", "options": ["厚植", "培养", "培育", "培植"], "answer": 0, "explanation": "「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选A。"}, {"id": "yy-18002", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "近年来，数据孤岛必须连起来，调解员下决心______部门间的壁垒。", "options": ["砸破", "击碎", "打碎", "打破"], "answer": 3, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选D。"}, {"id": "yy-18003", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "这些年，脱贫不是终点，审计人员多措并举______脱贫成果。", "options": ["凝固", "加固", "巩固", "稳固"], "answer": 2, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选C。"}, {"id": "yy-18004", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "近年来，每一起案件都关乎群众对法治的信仰，图书管理员用公正裁判______正义。", "options": ["防御", "护卫", "捍卫", "保卫"], "answer": 2, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选C。"}, {"id": "yy-18005", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，急难险重任务面前，护林员主动______最重的责任。", "options": ["抬起", "挑起", "背起", "扛起"], "answer": 3, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。"}, {"id": "yy-18006", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "眼下，一年一度的民生大考结束，广大建设者向群众______了温暖的答卷。", "options": ["上缴", "呈报", "递交", "交出"], "answer": 3, "explanation": "「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选D。"}, {"id": "yy-18007", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，发展为了人民，调解员把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增添", "增殖", "增进", "增加"], "answer": 2, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选C。"}, {"id": "yy-18008", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "近期，营商环境就是生产力，基层干部让企业成长有沃土。", "options": ["培育", "培植", "厚植", "培养"], "answer": 2, "explanation": "「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选C。"}, {"id": "yy-18009", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，一二三产融合发展，护林员推动产业链不断延伸。", "options": ["延伸", "伸长", "延长", "拉长"], "answer": 0, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选A。"}, {"id": "yy-18010", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "近期，每个孩子都有闪光点，调解员善于______学生潜能。", "options": ["挖掘", "开采", "挖出", "掘取"], "answer": 0, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选A。"}, {"id": "yy-18011", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近年来，一揽子政策精准落地，医护人员着力______市场信心。", "options": ["鼓动", "提振", "提起", "振作"], "answer": 1, "explanation": "「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选B。"}, {"id": "yy-18012", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "今年以来，万丈高楼平地起，渔民一锤一钎______发展基础。", "options": ["夯实", "填实", "踩实", "砸实"], "answer": 0, "explanation": "「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选A。"}, {"id": "yy-18013", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "一段时间以来，面对转型路上的重重难关，电力工人迎难而上，把一个个难关逐一______。", "options": ["克服", "攻克", "破除", "化解"], "answer": 1, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选B。"}, {"id": "yy-18014", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "一段时间以来，一二三产融合发展，医护人员推动产业链不断延伸。", "options": ["伸长", "拉长", "延长", "延伸"], "answer": 3, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。"}, {"id": "yy-18015", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "连日来，订单排到明年，果农发展的信心。", "options": ["倍受", "倍增", "加倍", "倍加"], "answer": 1, "explanation": "「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选B。"}, {"id": "yy-18016", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近年来，小哨兵大作用，乡村医生让基层网格______更大作用。", "options": ["施展", "表现", "发扬", "发挥"], "answer": 3, "explanation": "「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选D。"}, {"id": "yy-18017", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "近期，改革红利持续显现，市场活力不断，公交司机信心更足。", "options": ["爆发", "暴发", "迸发", "突发"], "answer": 2, "explanation": "「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。"}, {"id": "yy-18018", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "入冬以来，向存量要效益，图书管理员为产业升级______新空间。", "options": ["展开", "开展", "拓展", "拓开"], "answer": 2, "explanation": "「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选C。"}, {"id": "yy-18019", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，让公共服务覆盖城乡，电力工人持续______政策体系。", "options": ["完善", "完缮", "修完", "补完"], "answer": 0, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选A。"}, {"id": "yy-18020", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "眼下，内生动力从哪里来？志愿者们把功夫下在创新上。", "options": ["加强", "增强", "增添", "增大"], "answer": 1, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选B。"}, {"id": "yy-18021", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "入冬以来，订单排到明年，社区规划师发展的信心。", "options": ["倍加", "倍受", "倍增", "加倍"], "answer": 2, "explanation": "「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选C。"}, {"id": "yy-18022", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "岁末年初，营商环境就是生产力，法官让企业成长有沃土。", "options": ["厚植", "培养", "培育", "培植"], "answer": 0, "explanation": "「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选A。"}, {"id": "yy-18023", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "眼下，向存量要效益，博物馆讲解员为产业升级______新空间。", "options": ["开展", "拓展", "展开", "拓开"], "answer": 1, "explanation": "「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选B。"}, {"id": "yy-18024", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "今年以来，产业发展的根基越牢，抗风险的能力就越强，调解员深谙此理，先把根基打扎实。", "options": ["夯实", "垒砌", "铺设", "敲打"], "answer": 0, "explanation": "「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选A。"}, {"id": "yy-18025", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "今年以来，向存量要效益，调解员为产业升级______新空间。", "options": ["开展", "拓展", "展开", "拓开"], "answer": 1, "explanation": "「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选B。"}, {"id": "yy-18026", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "今年以来，誓师大会上，农技人员精神斗志，誓言响彻训练场。", "options": ["高昂", "昂扬", "高扬", "高涨"], "answer": 1, "explanation": "「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选B。"}, {"id": "yy-18027", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "这些年，金融活水精准滴灌，网格员为小微企业______发展动力。", "options": ["灌入", "灌输", "注入", "输入"], "answer": 2, "explanation": "「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选C。"}, {"id": "yy-18028", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "初秋时节，两岸同胞亲情割不断，图书管理员为青年交流______心灵心桥。", "options": ["铺设", "垒砌", "修筑", "架起"], "answer": 3, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选D。"}, {"id": "yy-18029", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，金融活水精准滴灌，快递员为小微企业______发展动力。", "options": ["注入", "输入", "灌入", "灌输"], "answer": 0, "explanation": "「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选A。"}, {"id": "yy-18030", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "盛夏时节，城乡公共服务仍有落差，基层干部以实策逐步______差距。", "options": ["缩减", "缩小", "减小", "减少"], "answer": 1, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选B。"}, {"id": "yy-18031", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "盛夏时节，发展为了人民，快递员把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增添", "增进", "增殖", "增加"], "answer": 1, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选B。"}, {"id": "yy-18032", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "今年以来，越是众声喧哗，越需要______共识，民警把大家的心拢到一起。", "options": ["凝聚", "冻住", "凝固", "凝结"], "answer": 0, "explanation": "「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选A。"}, {"id": "yy-18033", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "近年来，越是爬坡过坎，越要______必胜信心，手工艺人一步一个脚印向前走。", "options": ["坚持不懈", "坚定", "坚决", "坚强"], "answer": 1, "explanation": "「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选B。"}, {"id": "yy-18034", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "入冬以来，把家国情怀融入课堂，民警用身边故事打动学生。", "options": ["厚植", "浇灌", "培土", "施肥"], "answer": 0, "explanation": "「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选A。"}, {"id": "yy-18035", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "盛夏时节，纪律规矩挺在前面，广大建设者始终______纪律底线。", "options": ["遵守", "把守", "看守", "严守"], "answer": 3, "explanation": "「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选D。"}, {"id": "yy-18036", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "盛夏时节，跳出一时一地看发展，广大建设者着力______开放共赢的新格局。", "options": ["架造", "构作", "构建", "搭造"], "answer": 2, "explanation": "「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选C。"}, {"id": "yy-18037", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "今年以来，内生动力从哪里来？图书管理员把功夫下在创新上。", "options": ["增大", "加强", "增强", "增添"], "answer": 2, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选C。"}, {"id": "yy-18038", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，在广袤乡野间，医护人员用汗水______出乡村振兴的崭新篇章。", "options": ["描红", "抄写", "书写", "誊写"], "answer": 2, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选C。"}, {"id": "yy-18039", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "眼下，纪律规矩挺在前面，民警始终______纪律底线。", "options": ["把守", "遵守", "严守", "看守"], "answer": 2, "explanation": "「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选C。"}, {"id": "yy-18040", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "入冬以来，乡情是最深的牵挂，网格员以商会为平台______情感纽带。", "options": ["捆牢", "绑牢", "织牢", "系牢"], "answer": 2, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选C。"}, {"id": "yy-18041", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "连日来，向存量要效益，图书管理员为产业升级______新空间。", "options": ["展开", "拓开", "拓展", "开展"], "answer": 2, "explanation": "「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选C。"}, {"id": "yy-18042", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "初秋时节，面对转型路上的重重难关，医护人员迎难而上，把一个个难关逐一______。", "options": ["克服", "破除", "攻克", "化解"], "answer": 2, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选C。"}, {"id": "yy-18043", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "入冬以来，夜市灯火点亮街巷，图书管理员为城市______了烟火活力。", "options": ["增添", "增加", "追加", "增补"], "answer": 0, "explanation": "「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选A。"}, {"id": "yy-18044", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "近期，从受理到反馈全流程留痕，图书管理员以数字化手段______管理闭环。", "options": ["构建", "圈画", "搭圈", "构画"], "answer": 0, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选A。"}, {"id": "yy-18045", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "入冬以来，金融活水精准滴灌，茶农为小微企业______发展动力。", "options": ["注入", "灌输", "灌入", "输入"], "answer": 0, "explanation": "「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选A。"}, {"id": "yy-18046", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "入冬以来，传统村落保护性开发，文旅部门既富了口袋，也______了乡愁。", "options": ["留住", "拘留", "截留", "扣留"], "answer": 0, "explanation": "「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选A。"}, {"id": "yy-18047", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "一段时间以来，让要素流动更顺畅，就要______体制机制的藩篱。", "options": ["破除", "铲平", "捣毁", "拆除"], "answer": 0, "explanation": "「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选A。"}, {"id": "yy-18048", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，一次次说到做到，驻村干部用行动______了群众的信任。", "options": ["获得", "博得", "换取", "赢得"], "answer": 3, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选D。"}, {"id": "yy-18049", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，景区客流高峰来临，图书管理员全员上岗______游览秩序。", "options": ["保护", "维护", "维持", "护卫"], "answer": 1, "explanation": "「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选B。"}, {"id": "yy-18050", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "岁末年初，齐抓共管不是一句口号，环卫工人推动齐抓共管合力。", "options": ["成形", "形成", "成型", "成立"], "answer": 1, "explanation": "「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选B。"}, {"id": "yy-18051", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "一段时间以来，老旧小区加装电梯、增设车位，社区规划师尽力______居民多样需求。", "options": ["充足", "满意", "充盈", "满足"], "answer": 3, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选D。"}, {"id": "yy-18052", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "初秋时节，众人的事情由众人商量，果农把各方______到规划图上。", "options": ["收拢", "凝聚", "归拢", "聚拢"], "answer": 1, "explanation": "「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选B。"}, {"id": "yy-18053", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "今年以来，危难时刻冲得上去，科研人员的行动______了共产党员的担当。", "options": ["暴露", "彰显", "显露", "显摆"], "answer": 1, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选B。"}, {"id": "yy-18054", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "岁末年初，老工业基地涅槃重生，社区工作者加快新旧动能步伐。", "options": ["转换", "改换", "转变", "变换"], "answer": 0, "explanation": "「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选A。"}, {"id": "yy-18055", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "初秋时节，面对转型路上的重重难关，社区工作者迎难而上，把一个个难关逐一______。", "options": ["化解", "攻克", "克服", "破除"], "answer": 1, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选B。"}, {"id": "yy-18056", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，从受理到反馈全流程留痕，调解员以数字化手段______管理闭环。", "options": ["圈画", "构建", "构画", "搭圈"], "answer": 1, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选B。"}, {"id": "yy-18057", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "连日来，从受理到反馈全流程留痕，审计人员以数字化手段______管理闭环。", "options": ["搭圈", "圈画", "构画", "构建"], "answer": 3, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选D。"}, {"id": "yy-18058", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "这些年，放宽准入激发创业热情，青年学子让创造活力。", "options": ["淌出", "涌出", "流出", "涌流"], "answer": 3, "explanation": "「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选D。"}, {"id": "yy-18059", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，老艺人收徒授艺，让千年技艺薪火。", "options": ["互传", "递送", "传递", "相传"], "answer": 3, "explanation": "「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选D。"}, {"id": "yy-18060", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "眼下，乡情是最深的牵挂，图书管理员以商会为平台______情感纽带。", "options": ["捆牢", "织牢", "绑牢", "系牢"], "answer": 1, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选B。"}, {"id": "yy-18061", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "入冬以来，夜市灯火点亮街巷，护林员为城市______了烟火活力。", "options": ["追加", "增补", "增添", "增加"], "answer": 2, "explanation": "「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选C。"}, {"id": "yy-18062", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，从受理到反馈全流程留痕，青年学子以数字化手段______管理闭环。", "options": ["构建", "构画", "圈画", "搭圈"], "answer": 0, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选A。"}, {"id": "yy-18063", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "初秋时节，夜市灯火点亮街巷，社区规划师为城市______了烟火活力。", "options": ["增添", "增补", "增加", "追加"], "answer": 0, "explanation": "「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选A。"}, {"id": "yy-18064", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "近期，新区建设的宏伟蓝图已经展开，渔民正把一张张蓝图变成施工图。", "options": ["耕耘", "绘就", "编织", "修筑"], "answer": 1, "explanation": "「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选B。"}, {"id": "yy-18065", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "近年来，两岸同胞亲情割不断，教师为青年交流______心灵心桥。", "options": ["垒砌", "铺设", "架起", "修筑"], "answer": 2, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选C。"}, {"id": "yy-18066", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近年来，减税降费政策落地，铁路养护工让企业真切感受到红利。", "options": ["散发", "发放", "发射", "释放"], "answer": 3, "explanation": "「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选D。"}, {"id": "yy-18067", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "眼下，每个孩子都有闪光点，志愿者们善于______学生潜能。", "options": ["掘取", "开采", "挖掘", "挖出"], "answer": 2, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选C。"}, {"id": "yy-18068", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，政府、市场、社会同向发力，公交司机让各方______成强大合力。", "options": ["汇聚", "汇合", "聚合", "汇集"], "answer": 0, "explanation": "「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选A。"}, {"id": "yy-18069", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近期，一揽子政策精准落地，审计人员着力______市场信心。", "options": ["提振", "振作", "鼓动", "提起"], "answer": 0, "explanation": "「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选A。"}, {"id": "yy-18070", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "一段时间以来，让公共服务覆盖城乡，渔民持续______政策体系。", "options": ["完善", "补完", "完缮", "修完"], "answer": 0, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选A。"}, {"id": "yy-18071", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "开春以来，夜市灯火点亮街巷，铁路养护工为城市______了烟火活力。", "options": ["增补", "增加", "增添", "追加"], "answer": 2, "explanation": "「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选C。"}, {"id": "yy-18072", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近年来，脱贫不是终点，老党员多措并举______脱贫成果。", "options": ["巩固", "凝固", "稳固", "加固"], "answer": 0, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。"}, {"id": "yy-18073", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "一段时间以来，众人的事情由众人商量，基层干部把各方______到规划图上。", "options": ["收拢", "聚拢", "归拢", "凝聚"], "answer": 3, "explanation": "「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选D。"}, {"id": "yy-18074", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "眼下，一年一度的民生大考结束，网格员向群众______了温暖的答卷。", "options": ["上缴", "呈报", "递交", "交出"], "answer": 3, "explanation": "「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选D。"}, {"id": "yy-18075", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "入冬以来，面对转型路上的重重难关，乡村医生迎难而上，把一个个难关逐一______。", "options": ["化解", "破除", "克服", "攻克"], "answer": 3, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。"}, {"id": "yy-18076", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "近期，两岸同胞亲情割不断，医护人员为青年交流______心灵心桥。", "options": ["修筑", "铺设", "架起", "垒砌"], "answer": 2, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选C。"}, {"id": "yy-18077", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "岁末年初，把资源优势变成产业优势，社区工作者下大气力______区域品牌。", "options": ["打造", "打制", "拍打", "锻打"], "answer": 0, "explanation": "「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选A。"}, {"id": "yy-18078", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "连日来，春潮拍岸千帆竞，快递员感受到创新活力。", "options": ["流出", "涌出", "淌动", "涌动"], "answer": 3, "explanation": "「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选D。"}, {"id": "yy-18079", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，政府、市场、社会同向发力，铁路养护工让各方______成强大合力。", "options": ["汇集", "汇聚", "汇合", "聚合"], "answer": 1, "explanation": "「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选B。"}, {"id": "yy-18080", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近年来，向存量要效益，程序员为产业升级______新空间。", "options": ["拓开", "开展", "拓展", "展开"], "answer": 2, "explanation": "「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选C。"}, {"id": "yy-18081", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "初秋时节，每一起案件都关乎群众对法治的信仰，程序员用公正裁判______正义。", "options": ["防御", "捍卫", "护卫", "保卫"], "answer": 1, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选B。"}, {"id": "yy-18082", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "连日来，把家国情怀融入课堂，审计人员用身边故事打动学生。", "options": ["施肥", "浇灌", "厚植", "培土"], "answer": 2, "explanation": "「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选C。"}, {"id": "yy-18083", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "盛夏时节，把资源优势变成产业优势，教师下大气力______区域品牌。", "options": ["打制", "锻打", "打造", "拍打"], "answer": 2, "explanation": "「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选C。"}, {"id": "yy-18084", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，减税降费政策落地，调解员让企业真切感受到红利。", "options": ["发射", "散发", "释放", "发放"], "answer": 2, "explanation": "「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选C。"}, {"id": "yy-18085", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "入冬以来，政府、市场、社会同向发力，电力工人让各方______成强大合力。", "options": ["汇聚", "汇集", "汇合", "聚合"], "answer": 0, "explanation": "「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选A。"}, {"id": "yy-18086", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "这些年，市场细胞活跃起来，公交司机让经济肌体活力。", "options": ["装满", "塞满", "充满", "填满"], "answer": 2, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选C。"}, {"id": "yy-18087", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "今年以来，越是爬坡过坎，越要______必胜信心，志愿者们一步一个脚印向前走。", "options": ["坚强", "坚持不懈", "坚决", "坚定"], "answer": 3, "explanation": "「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选D。"}, {"id": "yy-18088", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "开春以来，在广袤乡野间，志愿者们用汗水______出乡村振兴的崭新篇章。", "options": ["书写", "誊写", "描红", "抄写"], "answer": 0, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选A。"}, {"id": "yy-18089", "module": "yanyu", "diff": 3, "exam": "医疗编", "prompt": "一段时间以来，金杯银杯不如老百姓的口碑，民警把每件小事都当大事办。", "options": ["创立", "建立", "设立", "树立"], "answer": 3, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选D。"}, {"id": "yy-18090", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "岁末年初，一网通办让数据多跑路，社区工作者以流程再造______政务效能。", "options": ["提高", "拔高", "抬高", "提升"], "answer": 3, "explanation": "「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选D。"}, {"id": "yy-18091", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "这些年，数据孤岛必须连起来，程序员下决心______部门间的壁垒。", "options": ["打破", "砸破", "击碎", "打碎"], "answer": 0, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选A。"}, {"id": "yy-18092", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "今年以来，内生动力从哪里来？执法人员把功夫下在创新上。", "options": ["增大", "加强", "增添", "增强"], "answer": 3, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选D。"}, {"id": "yy-18093", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "开春以来，人才是创新的第一资源，铁路养护工把发展根基越培越厚。", "options": ["浇灌", "培土", "施肥", "厚植"], "answer": 3, "explanation": "「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选D。"}, {"id": "yy-18094", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "今年以来，让监督机制长出牙齿，快递员把制度笼子越扎越紧。", "options": ["修葺", "修复", "健全", "修理"], "answer": 2, "explanation": "「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选C。"}, {"id": "yy-18095", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "盛夏时节，市场细胞活跃起来，非遗传承人让经济肌体活力。", "options": ["装满", "塞满", "填满", "充满"], "answer": 3, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选D。"}, {"id": "yy-18096", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "岁末年初，新区建设的宏伟蓝图已经展开，博物馆讲解员正把一张张蓝图变成施工图。", "options": ["编织", "绘就", "耕耘", "修筑"], "answer": 1, "explanation": "「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选B。"}, {"id": "yy-18097", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "初秋时节，纪律规矩挺在前面，茶农始终______纪律底线。", "options": ["遵守", "严守", "看守", "把守"], "answer": 1, "explanation": "「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选B。"}, {"id": "yy-18098", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "近年来，卡脖子技术亟待攻坚，图书管理员集中力量______一个个瓶颈。", "options": ["捅破", "撞破", "冲破", "突破"], "answer": 3, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选D。"}, {"id": "yy-18099", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，二十年只做一件事，广大建设者在细分领域里做到极致。", "options": ["深挖", "深掘", "深耕", "深钻"], "answer": 2, "explanation": "「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选C。"}, {"id": "yy-18100", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "一段时间以来，向存量要效益，茶农为产业升级______新空间。", "options": ["拓展", "拓开", "展开", "开展"], "answer": 0, "explanation": "「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选A。"}, {"id": "yy-18101", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "今年以来，卡脖子技术亟待攻坚，手工艺人集中力量______一个个瓶颈。", "options": ["捅破", "冲破", "突破", "撞破"], "answer": 2, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选C。"}, {"id": "yy-18102", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近年来，卡脖子技术亟待攻坚，执法人员集中力量______一个个瓶颈。", "options": ["突破", "冲破", "捅破", "撞破"], "answer": 0, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选A。"}, {"id": "yy-18103", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "今年以来，几十年如一日，医护人员在平凡岗位上______着为民初心。", "options": ["坚守", "把守", "守卫", "保守"], "answer": 0, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选A。"}, {"id": "yy-18104", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "盛夏时节，民生领域还有欠账，老党员列出清单逐项______短板。", "options": ["修补", "补丁", "贴补", "补齐"], "answer": 3, "explanation": "「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选D。"}, {"id": "yy-18105", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "近年来，初心如磐，使命在肩，审计人员把承诺落到一件件小事上。", "options": ["履行", "践行", "执行", "旅行"], "answer": 1, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选B。"}, {"id": "yy-18106", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "今年以来，一二三产融合发展，社区规划师推动产业链不断延伸。", "options": ["延长", "延伸", "拉长", "伸长"], "answer": 1, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选B。"}, {"id": "yy-18107", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "岁末年初，人才是创新的第一资源，铁路养护工把发展根基越培越厚。", "options": ["施肥", "浇灌", "厚植", "培土"], "answer": 2, "explanation": "「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选C。"}, {"id": "yy-18108", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "连日来，每一起案件都关乎群众对法治的信仰，审计人员用公正裁判______正义。", "options": ["防御", "捍卫", "护卫", "保卫"], "answer": 1, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选B。"}, {"id": "yy-18109", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "近期，筑起生态安全屏障，渔民让青山常在绿水长流。", "options": ["砌牢", "筑牢", "锁牢", "拴牢"], "answer": 1, "explanation": "「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选B。"}, {"id": "yy-18110", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "盛夏时节，红色资源是最生动的教材，护林员让红色血脉代代相传。", "options": ["接续", "延续", "继续", "赓续"], "answer": 3, "explanation": "「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选D。"}, {"id": "yy-18111", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "近年来，新区建设的宏伟蓝图已经展开，调解员正把一张张蓝图变成施工图。", "options": ["耕耘", "绘就", "修筑", "编织"], "answer": 1, "explanation": "「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选B。"}, {"id": "yy-18112", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "这些年，内生动力从哪里来？驻村干部把功夫下在创新上。", "options": ["增添", "增强", "增大", "加强"], "answer": 1, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选B。"}, {"id": "yy-18113", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "开春以来，古城修缮不搞大拆大建，市场监管部门让千年文脉在街巷间静静流淌。", "options": ["续接", "延续", "接通", "连接"], "answer": 1, "explanation": "「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选B。"}, {"id": "yy-18114", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "开春以来，让监督机制长出牙齿，乡村医生把制度笼子越扎越紧。", "options": ["修葺", "修复", "修理", "健全"], "answer": 3, "explanation": "「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选D。"}, {"id": "yy-18115", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "岁末年初，营商环境就是生产力，非遗传承人让企业成长有沃土。", "options": ["培植", "培育", "培养", "厚植"], "answer": 3, "explanation": "「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选D。"}, {"id": "yy-18116", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "眼下，改革到了深水区，果农以钉钉子精神______工作局面。", "options": ["揭开", "翻开", "掀开", "打开"], "answer": 3, "explanation": "「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选D。"}, {"id": "yy-18117", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "入冬以来，越是众声喧哗，越需要______共识，渔民把大家的心拢到一起。", "options": ["凝固", "冻住", "凝聚", "凝结"], "answer": 2, "explanation": "「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选C。"}, {"id": "yy-18118", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "今年以来，急难险重任务面前，图书管理员主动______最重的责任。", "options": ["抬起", "背起", "挑起", "扛起"], "answer": 3, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。"}, {"id": "yy-18119", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "近年来，市场不是法外之地，网格员以制度______交易秩序。", "options": ["规定", "规范", "规正", "规整"], "answer": 1, "explanation": "「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选B。"}, {"id": "yy-18120", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "盛夏时节，停车难是城市治理的老大难，社区工作者用共享思维______了这一难题。", "options": ["解释", "解开", "解冻", "破解"], "answer": 3, "explanation": "「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选D。"}, {"id": "yy-18121", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "盛夏时节，新区建设的宏伟蓝图已经展开，驻村干部正把一张张蓝图变成施工图。", "options": ["绘就", "修筑", "耕耘", "编织"], "answer": 0, "explanation": "「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选A。"}, {"id": "yy-18122", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "盛夏时节，二十年只做一件事，科研人员在细分领域里做到极致。", "options": ["深挖", "深耕", "深掘", "深钻"], "answer": 1, "explanation": "「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选B。"}, {"id": "yy-18123", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "开春以来，城乡公共服务仍有落差，公交司机以实策逐步______差距。", "options": ["缩减", "减少", "缩小", "减小"], "answer": 2, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选C。"}, {"id": "yy-18124", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "一段时间以来，脱贫不是终点，治沙工人多措并举______脱贫成果。", "options": ["巩固", "加固", "凝固", "稳固"], "answer": 0, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。"}, {"id": "yy-18125", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "盛夏时节，政府、市场、社会同向发力，电力工人让各方______成强大合力。", "options": ["汇集", "聚合", "汇聚", "汇合"], "answer": 2, "explanation": "「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选C。"}, {"id": "yy-18126", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，一次次说到做到，教师用行动______了群众的信任。", "options": ["获得", "换取", "赢得", "博得"], "answer": 2, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选C。"}, {"id": "yy-18127", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "这些年，市场不是法外之地，青年学子以制度______交易秩序。", "options": ["规定", "规范", "规正", "规整"], "answer": 1, "explanation": "「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选B。"}, {"id": "yy-18128", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "岁末年初，让监督机制长出牙齿，快递员把制度笼子越扎越紧。", "options": ["修理", "修复", "健全", "修葺"], "answer": 2, "explanation": "「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选C。"}, {"id": "yy-18129", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "初秋时节，数据孤岛必须连起来，文旅部门下决心______部门间的壁垒。", "options": ["打破", "打碎", "砸破", "击碎"], "answer": 0, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选A。"}, {"id": "yy-18130", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "一段时间以来，新区建设的宏伟蓝图已经展开，手工艺人正把一张张蓝图变成施工图。", "options": ["修筑", "绘就", "编织", "耕耘"], "answer": 1, "explanation": "「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选B。"}, {"id": "yy-18131", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "初秋时节，改革红利持续显现，市场活力不断，工程师信心更足。", "options": ["爆发", "突发", "迸发", "暴发"], "answer": 2, "explanation": "「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。"}, {"id": "yy-18132", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "盛夏时节，改革到了深水区，治沙工人以钉钉子精神______工作局面。", "options": ["揭开", "翻开", "掀开", "打开"], "answer": 3, "explanation": "「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选D。"}, {"id": "yy-18133", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "眼下，危难时刻冲得上去，环卫工人的行动______了共产党员的担当。", "options": ["显露", "暴露", "显摆", "彰显"], "answer": 3, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选D。"}, {"id": "yy-18134", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "眼下，让新业态释放新动能，法官在制度创新上先行先试。", "options": ["发动", "激发", "点燃", "引爆"], "answer": 1, "explanation": "「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选B。"}, {"id": "yy-18135", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "连日来，让新业态释放新动能，医护人员在制度创新上先行先试。", "options": ["点燃", "激发", "引爆", "发动"], "answer": 1, "explanation": "「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选B。"}, {"id": "yy-18136", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "连日来，危难时刻冲得上去，青年学子的行动______了共产党员的担当。", "options": ["彰显", "显摆", "显露", "暴露"], "answer": 0, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选A。"}, {"id": "yy-18137", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "今年以来，齐抓共管不是一句口号，环卫工人推动齐抓共管合力。", "options": ["形成", "成型", "成立", "成形"], "answer": 0, "explanation": "「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选A。"}, {"id": "yy-18138", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，把风险挺在前面，社区工作者织密织牢安全网。", "options": ["防守", "防备", "防范", "提防"], "answer": 2, "explanation": "「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选C。"}, {"id": "yy-18139", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "盛夏时节，齐抓共管不是一句口号，老党员推动齐抓共管合力。", "options": ["成形", "成立", "形成", "成型"], "answer": 2, "explanation": "「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选C。"}, {"id": "yy-18140", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "今年以来，二十年只做一件事，教师在细分领域里做到极致。", "options": ["深挖", "深掘", "深耕", "深钻"], "answer": 2, "explanation": "「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选C。"}, {"id": "yy-18141", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "近年来，安全底线不可逾越，治沙工人24小时轮班值守。", "options": ["看守", "把守", "镇守", "坚守"], "answer": 3, "explanation": "「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选D。"}, {"id": "yy-18142", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近期，汛期将至，设计师对辖区地质灾害隐患逐点______。", "options": ["普查", "检察", "检查", "排查"], "answer": 3, "explanation": "「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选D。"}, {"id": "yy-18143", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "初秋时节，每一起案件都关乎群众对法治的信仰，果农用公正裁判______正义。", "options": ["防御", "保卫", "捍卫", "护卫"], "answer": 2, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选C。"}, {"id": "yy-18144", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近年来，纪律规矩挺在前面，驻村干部始终______纪律底线。", "options": ["把守", "遵守", "看守", "严守"], "answer": 3, "explanation": "「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选D。"}, {"id": "yy-18145", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "岁末年初，数据孤岛必须连起来，电力工人下决心______部门间的壁垒。", "options": ["打碎", "打破", "砸破", "击碎"], "answer": 1, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选B。"}, {"id": "yy-18146", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "一段时间以来，发展为了人民，治沙工人把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增添", "增殖", "增加", "增进"], "answer": 3, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选D。"}, {"id": "yy-18147", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "一段时间以来，市场细胞活跃起来，果农让经济肌体活力。", "options": ["填满", "充满", "装满", "塞满"], "answer": 1, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选B。"}, {"id": "yy-18148", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "盛夏时节，传统村落保护性开发，果农既富了口袋，也______了乡愁。", "options": ["留住", "拘留", "截留", "扣留"], "answer": 0, "explanation": "「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选A。"}, {"id": "yy-18149", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "连日来，让监督机制长出牙齿，驻村干部把制度笼子越扎越紧。", "options": ["健全", "修复", "修葺", "修理"], "answer": 0, "explanation": "「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选A。"}, {"id": "yy-18150", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近年来，把监督防线扎到最基层，公交司机走村入户听民声。", "options": ["织补", "缝密", "织密", "织厚"], "answer": 2, "explanation": "「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选C。"}, {"id": "yy-18151", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "入冬以来，改革红利持续显现，市场活力不断，广大建设者信心更足。", "options": ["爆发", "突发", "暴发", "迸发"], "answer": 3, "explanation": "「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选D。"}, {"id": "yy-18152", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，汛期将至，志愿者们对辖区地质灾害隐患逐点______。", "options": ["检查", "普查", "检察", "排查"], "answer": 3, "explanation": "「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选D。"}, {"id": "yy-18153", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "一段时间以来，小哨兵大作用，程序员让基层网格______更大作用。", "options": ["表现", "发挥", "施展", "发扬"], "answer": 1, "explanation": "「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选B。"}, {"id": "yy-18154", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "岁末年初，把消费潜力转化为增长实绩，科研人员拿出了实招硬招。", "options": ["发泄", "喷发", "散发", "释放"], "answer": 3, "explanation": "「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选D。"}, {"id": "yy-18155", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "这些年，危难时刻冲得上去，科研人员的行动______了共产党员的担当。", "options": ["显摆", "暴露", "彰显", "显露"], "answer": 2, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选C。"}, {"id": "yy-18156", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "盛夏时节，一年一度的民生大考结束，广大建设者向群众______了温暖的答卷。", "options": ["上缴", "交出", "呈报", "递交"], "answer": 1, "explanation": "「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选B。"}, {"id": "yy-18157", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "入冬以来，从受理到反馈全流程留痕，医护人员以数字化手段______管理闭环。", "options": ["搭圈", "构建", "构画", "圈画"], "answer": 1, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选B。"}, {"id": "yy-18158", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，让新业态释放新动能，医护人员在制度创新上先行先试。", "options": ["激发", "引爆", "发动", "点燃"], "answer": 0, "explanation": "「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选A。"}, {"id": "yy-18159", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "岁末年初，初心如磐，使命在肩，手工艺人把承诺落到一件件小事上。", "options": ["履行", "旅行", "践行", "执行"], "answer": 2, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选C。"}, {"id": "yy-18160", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "今年以来，产业发展的根基越牢，抗风险的能力就越强，非遗传承人深谙此理，先把根基打扎实。", "options": ["敲打", "铺设", "垒砌", "夯实"], "answer": 3, "explanation": "「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选D。"}, {"id": "yy-18161", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "开春以来，放宽准入激发创业热情，教师让创造活力。", "options": ["涌流", "淌出", "涌出", "流出"], "answer": 0, "explanation": "「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选A。"}, {"id": "yy-18162", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "入冬以来，金杯银杯不如老百姓的口碑，果农把每件小事都当大事办。", "options": ["创立", "设立", "建立", "树立"], "answer": 3, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选D。"}, {"id": "yy-18163", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "今年以来，一二三产融合发展，基层干部推动产业链不断延伸。", "options": ["伸长", "延长", "拉长", "延伸"], "answer": 3, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。"}, {"id": "yy-18164", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "初秋时节，让公共服务覆盖城乡，图书管理员持续______政策体系。", "options": ["完缮", "补完", "修完", "完善"], "answer": 3, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选D。"}, {"id": "yy-18165", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近期，乡情是最深的牵挂，设计师以商会为平台______情感纽带。", "options": ["织牢", "绑牢", "捆牢", "系牢"], "answer": 0, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。"}, {"id": "yy-18166", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，城乡公共服务仍有落差，科研人员以实策逐步______差距。", "options": ["减少", "减小", "缩小", "缩减"], "answer": 2, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选C。"}, {"id": "yy-18167", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，几十年如一日，博物馆讲解员在平凡岗位上______着为民初心。", "options": ["保守", "把守", "守卫", "坚守"], "answer": 3, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选D。"}, {"id": "yy-18168", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "一段时间以来，众人的事情由众人商量，社区规划师把各方______到规划图上。", "options": ["收拢", "归拢", "凝聚", "聚拢"], "answer": 2, "explanation": "「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选C。"}, {"id": "yy-18169", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "初秋时节，众人的事情由众人商量，工程师把各方______到规划图上。", "options": ["凝聚", "收拢", "聚拢", "归拢"], "answer": 0, "explanation": "「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选A。"}, {"id": "yy-18170", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "近期，一二三产融合发展，民警推动产业链不断延伸。", "options": ["延长", "拉长", "伸长", "延伸"], "answer": 3, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。"}, {"id": "yy-18171", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "眼下，筑起生态安全屏障，茶农让青山常在绿水长流。", "options": ["筑牢", "砌牢", "拴牢", "锁牢"], "answer": 0, "explanation": "「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选A。"}, {"id": "yy-18172", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "一段时间以来，民生实事清单公示上墙，博物馆讲解员一件一件______承诺。", "options": ["实现", "达成", "兑现", "完成"], "answer": 2, "explanation": "「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选C。"}, {"id": "yy-18173", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，景区客流高峰来临，工程师全员上岗______游览秩序。", "options": ["维持", "维护", "保护", "护卫"], "answer": 1, "explanation": "「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选B。"}, {"id": "yy-18174", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "近期，减税降费政策落地，教师让企业真切感受到红利。", "options": ["散发", "发射", "发放", "释放"], "answer": 3, "explanation": "「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选D。"}, {"id": "yy-18175", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "岁末年初，急难险重任务面前，非遗传承人主动______最重的责任。", "options": ["挑起", "抬起", "背起", "扛起"], "answer": 3, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。"}, {"id": "yy-18176", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，把风险挺在前面，茶农织密织牢安全网。", "options": ["提防", "防守", "防备", "防范"], "answer": 3, "explanation": "「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选D。"}, {"id": "yy-18177", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "初秋时节，产业发展的根基越牢，抗风险的能力就越强，法官深谙此理，先把根基打扎实。", "options": ["敲打", "垒砌", "夯实", "铺设"], "answer": 2, "explanation": "「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选C。"}, {"id": "yy-18178", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "今年以来，面对转型路上的重重难关，调解员迎难而上，把一个个难关逐一______。", "options": ["化解", "克服", "破除", "攻克"], "answer": 3, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。"}, {"id": "yy-18179", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近期，脱贫不是终点，图书管理员多措并举______脱贫成果。", "options": ["稳固", "巩固", "凝固", "加固"], "answer": 1, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选B。"}, {"id": "yy-18180", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "岁末年初，发展为了人民，环卫工人把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增加", "增进", "增殖", "增添"], "answer": 1, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选B。"}, {"id": "yy-18181", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "岁末年初，产业发展的根基越牢，抗风险的能力就越强，社区规划师深谙此理，先把根基打扎实。", "options": ["夯实", "垒砌", "敲打", "铺设"], "answer": 0, "explanation": "「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选A。"}, {"id": "yy-18182", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "入冬以来，一年一度的民生大考结束，博物馆讲解员向群众______了温暖的答卷。", "options": ["递交", "交出", "上缴", "呈报"], "answer": 1, "explanation": "「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选B。"}, {"id": "yy-18183", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，城乡公共服务仍有落差，市场监管部门以实策逐步______差距。", "options": ["缩减", "减少", "减小", "缩小"], "answer": 3, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选D。"}, {"id": "yy-18184", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "近年来，从受理到反馈全流程留痕，审计人员以数字化手段______管理闭环。", "options": ["圈画", "构建", "构画", "搭圈"], "answer": 1, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选B。"}, {"id": "yy-18185", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "这些年，每个孩子都有闪光点，老党员善于______学生潜能。", "options": ["挖出", "掘取", "挖掘", "开采"], "answer": 2, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选C。"}, {"id": "yy-18186", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "近年来，市场细胞活跃起来，渔民让经济肌体活力。", "options": ["装满", "填满", "充满", "塞满"], "answer": 2, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选C。"}, {"id": "yy-18187", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，筑起生态安全屏障，青年学子让青山常在绿水长流。", "options": ["砌牢", "锁牢", "筑牢", "拴牢"], "answer": 2, "explanation": "「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选C。"}, {"id": "yy-18188", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "入冬以来，一二三产融合发展，科研人员推动产业链不断延伸。", "options": ["延伸", "伸长", "拉长", "延长"], "answer": 0, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选A。"}, {"id": "yy-18189", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，卡脖子技术亟待攻坚，执法人员集中力量______一个个瓶颈。", "options": ["突破", "冲破", "撞破", "捅破"], "answer": 0, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选A。"}, {"id": "yy-18190", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，绿水青山就是金山银山，消防员代代接力______绿色生态。", "options": ["守护", "守望", "守候", "看守"], "answer": 0, "explanation": "「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选A。"}, {"id": "yy-18191", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "初秋时节，数据孤岛必须连起来，图书管理员下决心______部门间的壁垒。", "options": ["砸破", "打碎", "打破", "击碎"], "answer": 2, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选C。"}, {"id": "yy-18192", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "入冬以来，两岸同胞亲情割不断，志愿者们为青年交流______心灵心桥。", "options": ["铺设", "修筑", "架起", "垒砌"], "answer": 2, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选C。"}, {"id": "yy-18193", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近期，面对转型路上的重重难关，渔民迎难而上，把一个个难关逐一______。", "options": ["克服", "化解", "破除", "攻克"], "answer": 3, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。"}, {"id": "yy-18194", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "眼下，让新业态释放新动能，茶农在制度创新上先行先试。", "options": ["激发", "引爆", "发动", "点燃"], "answer": 0, "explanation": "「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选A。"}, {"id": "yy-18195", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，春潮拍岸千帆竞，农技人员感受到创新活力。", "options": ["涌动", "淌动", "涌出", "流出"], "answer": 0, "explanation": "「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选A。"}, {"id": "yy-18196", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "岁末年初，把风险挺在前面，科研人员织密织牢安全网。", "options": ["防范", "防备", "防守", "提防"], "answer": 0, "explanation": "「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选A。"}, {"id": "yy-18197", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "今年以来，一揽子政策精准落地，调解员着力______市场信心。", "options": ["振作", "提起", "提振", "鼓动"], "answer": 2, "explanation": "「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选C。"}, {"id": "yy-18198", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，誓师大会上，老党员精神斗志，誓言响彻训练场。", "options": ["高扬", "高涨", "高昂", "昂扬"], "answer": 3, "explanation": "「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选D。"}, {"id": "yy-18199", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "岁末年初，一网通办让数据多跑路，执法人员以流程再造______政务效能。", "options": ["拔高", "提升", "抬高", "提高"], "answer": 1, "explanation": "「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选B。"}, {"id": "yy-18200", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "盛夏时节，市场不是法外之地，青年学子以制度______交易秩序。", "options": ["规范", "规定", "规正", "规整"], "answer": 0, "explanation": "「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选A。"}, {"id": "yy-18201", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，几十年如一日，环卫工人在平凡岗位上______着为民初心。", "options": ["坚守", "保守", "守卫", "把守"], "answer": 0, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选A。"}, {"id": "yy-18202", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，金杯银杯不如老百姓的口碑，图书管理员把每件小事都当大事办。", "options": ["创立", "设立", "树立", "建立"], "answer": 2, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选C。"}, {"id": "yy-18203", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "初秋时节，乡情是最深的牵挂，快递员以商会为平台______情感纽带。", "options": ["织牢", "绑牢", "捆牢", "系牢"], "answer": 0, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。"}, {"id": "yy-18204", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，跳出一时一地看发展，驻村干部着力______开放共赢的新格局。", "options": ["搭造", "架造", "构建", "构作"], "answer": 2, "explanation": "「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选C。"}, {"id": "yy-18205", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "这些年，在广袤乡野间，广大建设者用汗水______出乡村振兴的崭新篇章。", "options": ["描红", "誊写", "抄写", "书写"], "answer": 3, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选D。"}, {"id": "yy-18206", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "今年以来，让公共服务覆盖城乡，市场监管部门持续______政策体系。", "options": ["补完", "修完", "完善", "完缮"], "answer": 2, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选C。"}, {"id": "yy-18207", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "开春以来，金杯银杯不如老百姓的口碑，老党员把每件小事都当大事办。", "options": ["设立", "树立", "创立", "建立"], "answer": 1, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选B。"}, {"id": "yy-18208", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "岁末年初，向存量要效益，铁路养护工为产业升级______新空间。", "options": ["拓开", "开展", "展开", "拓展"], "answer": 3, "explanation": "「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选D。"}, {"id": "yy-18209", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "一段时间以来，夜市灯火点亮街巷，手工艺人为城市______了烟火活力。", "options": ["增加", "增补", "增添", "追加"], "answer": 2, "explanation": "「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选C。"}, {"id": "yy-18210", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近年来，把家国情怀融入课堂，青年学子用身边故事打动学生。", "options": ["浇灌", "厚植", "施肥", "培土"], "answer": 1, "explanation": "「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选B。"}, {"id": "yy-18211", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "盛夏时节，老旧小区加装电梯、增设车位，电力工人尽力______居民多样需求。", "options": ["充盈", "充足", "满意", "满足"], "answer": 3, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选D。"}, {"id": "yy-18212", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "岁末年初，产业发展的根基越牢，抗风险的能力就越强，护林员深谙此理，先把根基打扎实。", "options": ["垒砌", "铺设", "敲打", "夯实"], "answer": 3, "explanation": "「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选D。"}, {"id": "yy-18213", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "眼下，老艺人收徒授艺，让千年技艺薪火。", "options": ["相传", "递送", "传递", "互传"], "answer": 0, "explanation": "「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选A。"}, {"id": "yy-18214", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，金杯银杯不如老百姓的口碑，公交司机把每件小事都当大事办。", "options": ["创立", "建立", "树立", "设立"], "answer": 2, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选C。"}, {"id": "yy-18215", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "近期，数据孤岛必须连起来，环卫工人下决心______部门间的壁垒。", "options": ["砸破", "打碎", "击碎", "打破"], "answer": 3, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选D。"}, {"id": "yy-18216", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "近期，被动状态必须改变，渔民用硬措施______了不利局面。", "options": ["反转", "倒转", "扭转", "回转"], "answer": 2, "explanation": "「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选C。"}, {"id": "yy-18217", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "今年以来，两岸同胞亲情割不断，乡村医生为青年交流______心灵心桥。", "options": ["铺设", "修筑", "垒砌", "架起"], "answer": 3, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选D。"}, {"id": "yy-18218", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "开春以来，老厂房变身文创园，乡村医生让工业遗存______新的活力。", "options": ["焕发", "焕新", "换发", "更新"], "answer": 0, "explanation": "「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选A。"}, {"id": "yy-18219", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "入冬以来，停车难是城市治理的老大难，治沙工人用共享思维______了这一难题。", "options": ["解开", "解释", "解冻", "破解"], "answer": 3, "explanation": "「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选D。"}, {"id": "yy-18220", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "入冬以来，每个孩子都有闪光点，青年学子善于______学生潜能。", "options": ["开采", "掘取", "挖出", "挖掘"], "answer": 3, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。"}, {"id": "yy-18221", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "开春以来，卡脖子技术亟待攻坚，广大建设者集中力量______一个个瓶颈。", "options": ["撞破", "捅破", "冲破", "突破"], "answer": 3, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选D。"}, {"id": "yy-18222", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "初秋时节，把监督防线扎到最基层，调解员走村入户听民声。", "options": ["缝密", "织密", "织补", "织厚"], "answer": 1, "explanation": "「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选B。"}, {"id": "yy-18223", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，营商环境就是生产力，手工艺人让企业成长有沃土。", "options": ["培育", "培养", "培植", "厚植"], "answer": 3, "explanation": "「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选D。"}, {"id": "yy-18224", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "一段时间以来，卡脖子技术亟待攻坚，工程师集中力量______一个个瓶颈。", "options": ["捅破", "撞破", "冲破", "突破"], "answer": 3, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选D。"}, {"id": "yy-18225", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，让新业态释放新动能，基层干部在制度创新上先行先试。", "options": ["引爆", "点燃", "发动", "激发"], "answer": 3, "explanation": "「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选D。"}, {"id": "yy-18226", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "一段时间以来，数据孤岛必须连起来，护林员下决心______部门间的壁垒。", "options": ["打破", "砸破", "击碎", "打碎"], "answer": 0, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选A。"}, {"id": "yy-18227", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "这些年，老艺人收徒授艺，让千年技艺薪火。", "options": ["传递", "递送", "互传", "相传"], "answer": 3, "explanation": "「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选D。"}, {"id": "yy-18228", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "一段时间以来，在广袤乡野间，市场监管部门用汗水______出乡村振兴的崭新篇章。", "options": ["誊写", "描红", "书写", "抄写"], "answer": 2, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选C。"}, {"id": "yy-18229", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "眼下，两岸同胞亲情割不断，电力工人为青年交流______心灵心桥。", "options": ["修筑", "垒砌", "铺设", "架起"], "answer": 3, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选D。"}, {"id": "yy-18230", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "初秋时节，政府、市场、社会同向发力，公交司机让各方______成强大合力。", "options": ["汇聚", "聚合", "汇合", "汇集"], "answer": 0, "explanation": "「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选A。"}, {"id": "yy-18231", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "入冬以来，内生动力从哪里来？医护人员把功夫下在创新上。", "options": ["增强", "增添", "加强", "增大"], "answer": 0, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选A。"}, {"id": "yy-18232", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近年来，老艺人收徒授艺，让千年技艺薪火。", "options": ["相传", "传递", "互传", "递送"], "answer": 0, "explanation": "「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选A。"}, {"id": "yy-18233", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "今年以来，一次次说到做到，非遗传承人用行动______了群众的信任。", "options": ["博得", "换取", "获得", "赢得"], "answer": 3, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选D。"}, {"id": "yy-18234", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "连日来，老厂房变身文创园，茶农让工业遗存______新的活力。", "options": ["换发", "更新", "焕新", "焕发"], "answer": 3, "explanation": "「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选D。"}, {"id": "yy-18235", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "近期，景区客流高峰来临，网格员全员上岗______游览秩序。", "options": ["护卫", "维持", "维护", "保护"], "answer": 2, "explanation": "「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选C。"}, {"id": "yy-18236", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近期，把风险挺在前面，广大建设者织密织牢安全网。", "options": ["防守", "防备", "提防", "防范"], "answer": 3, "explanation": "「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选D。"}, {"id": "yy-18237", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，减税降费政策落地，茶农让企业真切感受到红利。", "options": ["发射", "发放", "释放", "散发"], "answer": 2, "explanation": "「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选C。"}, {"id": "yy-18238", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "入冬以来，跳出一时一地看发展，图书管理员着力______开放共赢的新格局。", "options": ["构建", "构作", "架造", "搭造"], "answer": 0, "explanation": "「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选A。"}, {"id": "yy-18239", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "开春以来，手握核心技术专利，图书管理员创新的底气。", "options": ["更硬", "更强", "更足", "更壮"], "answer": 2, "explanation": "「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选C。"}, {"id": "yy-18240", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "入冬以来，民生实事清单公示上墙，志愿者们一件一件______承诺。", "options": ["实现", "兑现", "完成", "达成"], "answer": 1, "explanation": "「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选B。"}, {"id": "yy-18241", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "今年以来，小哨兵大作用，农技人员让基层网格______更大作用。", "options": ["施展", "发挥", "发扬", "表现"], "answer": 1, "explanation": "「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选B。"}, {"id": "yy-18242", "module": "yanyu", "diff": 3, "exam": "医疗编", "prompt": "入冬以来，几十年如一日，程序员在平凡岗位上______着为民初心。", "options": ["坚守", "守卫", "保守", "把守"], "answer": 0, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选A。"}, {"id": "yy-18243", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "开春以来，把消费潜力转化为增长实绩，乡村医生拿出了实招硬招。", "options": ["释放", "散发", "发泄", "喷发"], "answer": 0, "explanation": "「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选A。"}, {"id": "yy-18244", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "盛夏时节，一年一度的民生大考结束，志愿者们向群众______了温暖的答卷。", "options": ["递交", "上缴", "交出", "呈报"], "answer": 2, "explanation": "「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选C。"}, {"id": "yy-18245", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "这些年，卡脖子技术亟待攻坚，手工艺人集中力量______一个个瓶颈。", "options": ["捅破", "冲破", "撞破", "突破"], "answer": 3, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选D。"}, {"id": "yy-18246", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "初秋时节，几十年如一日，消防员在平凡岗位上______着为民初心。", "options": ["把守", "守卫", "保守", "坚守"], "answer": 3, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选D。"}, {"id": "yy-18247", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "眼下，每一起案件都关乎群众对法治的信仰，老党员用公正裁判______正义。", "options": ["捍卫", "保卫", "防御", "护卫"], "answer": 0, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选A。"}, {"id": "yy-18248", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "入冬以来，内生动力从哪里来？博物馆讲解员把功夫下在创新上。", "options": ["增添", "增强", "加强", "增大"], "answer": 1, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选B。"}, {"id": "yy-18249", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "岁末年初，老旧小区加装电梯、增设车位，渔民尽力______居民多样需求。", "options": ["满足", "满意", "充足", "充盈"], "answer": 0, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选A。"}, {"id": "yy-18250", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "开春以来，改革红利持续显现，市场活力不断，乡村医生信心更足。", "options": ["暴发", "突发", "迸发", "爆发"], "answer": 2, "explanation": "「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。"}, {"id": "yy-18251", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "近期，让监督机制长出牙齿，志愿者们把制度笼子越扎越紧。", "options": ["修复", "修葺", "健全", "修理"], "answer": 2, "explanation": "「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选C。"}, {"id": "yy-18252", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，金融活水精准滴灌，驻村干部为小微企业______发展动力。", "options": ["输入", "注入", "灌输", "灌入"], "answer": 1, "explanation": "「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选B。"}, {"id": "yy-18253", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "盛夏时节，改革红利持续显现，市场活力不断，图书管理员信心更足。", "options": ["爆发", "暴发", "迸发", "突发"], "answer": 2, "explanation": "「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。"}, {"id": "yy-18254", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "近年来，从受理到反馈全流程留痕，调解员以数字化手段______管理闭环。", "options": ["构画", "圈画", "搭圈", "构建"], "answer": 3, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选D。"}, {"id": "yy-18255", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "今年以来，金融活水精准滴灌，法官为小微企业______发展动力。", "options": ["输入", "注入", "灌入", "灌输"], "answer": 1, "explanation": "「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选B。"}, {"id": "yy-18256", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "入冬以来，古城修缮不搞大拆大建，渔民让千年文脉在街巷间静静流淌。", "options": ["续接", "连接", "延续", "接通"], "answer": 2, "explanation": "「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选C。"}, {"id": "yy-18257", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "近年来，向存量要效益，审计人员为产业升级______新空间。", "options": ["拓展", "展开", "拓开", "开展"], "answer": 0, "explanation": "「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选A。"}, {"id": "yy-18258", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，让农产品出村进城，执法人员多方合力______销售通道。", "options": ["扩宽", "开宽", "拓宽", "开辟"], "answer": 2, "explanation": "「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选C。"}, {"id": "yy-18259", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "入冬以来，金杯银杯不如老百姓的口碑，护林员把每件小事都当大事办。", "options": ["建立", "树立", "设立", "创立"], "answer": 1, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选B。"}, {"id": "yy-18260", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "今年以来，数据孤岛必须连起来，程序员下决心______部门间的壁垒。", "options": ["击碎", "砸破", "打破", "打碎"], "answer": 2, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选C。"}, {"id": "yy-18261", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，老工业基地涅槃重生，设计师加快新旧动能步伐。", "options": ["改换", "转换", "变换", "转变"], "answer": 1, "explanation": "「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选B。"}, {"id": "yy-18262", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "这些年，让要素流动更顺畅，就要______体制机制的藩篱。", "options": ["捣毁", "铲平", "拆除", "破除"], "answer": 3, "explanation": "「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选D。"}, {"id": "yy-18263", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "连日来，减税降费政策落地，医护人员让企业真切感受到红利。", "options": ["发射", "释放", "发放", "散发"], "answer": 1, "explanation": "「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选B。"}, {"id": "yy-18264", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，万丈高楼平地起，执法人员一锤一钎______发展基础。", "options": ["填实", "踩实", "夯实", "砸实"], "answer": 2, "explanation": "「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选C。"}, {"id": "yy-18265", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "近年来，政府、市场、社会同向发力，税务干部让各方______成强大合力。", "options": ["汇聚", "聚合", "汇集", "汇合"], "answer": 0, "explanation": "「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选A。"}, {"id": "yy-18266", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，改革红利持续显现，市场活力不断，手工艺人信心更足。", "options": ["暴发", "爆发", "迸发", "突发"], "answer": 2, "explanation": "「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。"}, {"id": "yy-18267", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "今年以来，一二三产融合发展，治沙工人推动产业链不断延伸。", "options": ["拉长", "延长", "延伸", "伸长"], "answer": 2, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选C。"}, {"id": "yy-18268", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "连日来，营商环境就是生产力，法官让企业成长有沃土。", "options": ["培植", "厚植", "培育", "培养"], "answer": 1, "explanation": "「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选B。"}, {"id": "yy-18269", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "初秋时节，人才是创新的第一资源，调解员把发展根基越培越厚。", "options": ["培土", "浇灌", "厚植", "施肥"], "answer": 2, "explanation": "「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选C。"}, {"id": "yy-18270", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，每个孩子都有闪光点，治沙工人善于______学生潜能。", "options": ["开采", "掘取", "挖出", "挖掘"], "answer": 3, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。"}, {"id": "yy-18271", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "开春以来，从受理到反馈全流程留痕，审计人员以数字化手段______管理闭环。", "options": ["圈画", "构建", "构画", "搭圈"], "answer": 1, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选B。"}, {"id": "yy-18272", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "初秋时节，老艺人收徒授艺，让千年技艺薪火。", "options": ["互传", "相传", "递送", "传递"], "answer": 1, "explanation": "「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选B。"}, {"id": "yy-18273", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，手握核心技术专利，执法人员创新的底气。", "options": ["更足", "更强", "更壮", "更硬"], "answer": 0, "explanation": "「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选A。"}, {"id": "yy-18274", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "开春以来，夜市灯火点亮街巷，渔民为城市______了烟火活力。", "options": ["增添", "追加", "增补", "增加"], "answer": 0, "explanation": "「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选A。"}, {"id": "yy-18275", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "这些年，停车难是城市治理的老大难，工程师用共享思维______了这一难题。", "options": ["解冻", "解释", "破解", "解开"], "answer": 2, "explanation": "「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选C。"}, {"id": "yy-18276", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，绿水青山就是金山银山，志愿者们代代接力______绿色生态。", "options": ["守望", "守护", "看守", "守候"], "answer": 1, "explanation": "「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选B。"}, {"id": "yy-18277", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "连日来，市场细胞活跃起来，手工艺人让经济肌体活力。", "options": ["填满", "装满", "充满", "塞满"], "answer": 2, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选C。"}, {"id": "yy-18278", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "入冬以来，景区客流高峰来临，博物馆讲解员全员上岗______游览秩序。", "options": ["保护", "维护", "护卫", "维持"], "answer": 1, "explanation": "「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选B。"}, {"id": "yy-18279", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "今年以来，市场不是法外之地，程序员以制度______交易秩序。", "options": ["规整", "规正", "规定", "规范"], "answer": 3, "explanation": "「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选D。"}, {"id": "yy-18280", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "一段时间以来，城乡公共服务仍有落差，博物馆讲解员以实策逐步______差距。", "options": ["减少", "减小", "缩减", "缩小"], "answer": 3, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选D。"}, {"id": "yy-18281", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "盛夏时节，被动状态必须改变，网格员用硬措施______了不利局面。", "options": ["扭转", "倒转", "反转", "回转"], "answer": 0, "explanation": "「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选A。"}, {"id": "yy-18282", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "今年以来，小哨兵大作用，市场监管部门让基层网格______更大作用。", "options": ["发挥", "施展", "发扬", "表现"], "answer": 0, "explanation": "「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选A。"}, {"id": "yy-18283", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "今年以来，一年一度的民生大考结束，快递员向群众______了温暖的答卷。", "options": ["呈报", "上缴", "递交", "交出"], "answer": 3, "explanation": "「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选D。"}, {"id": "yy-18284", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "一段时间以来，民生领域还有欠账，环卫工人列出清单逐项______短板。", "options": ["修补", "补丁", "贴补", "补齐"], "answer": 3, "explanation": "「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选D。"}, {"id": "yy-18285", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "初秋时节，在广袤乡野间，乡村医生用汗水______出乡村振兴的崭新篇章。", "options": ["誊写", "描红", "抄写", "书写"], "answer": 3, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选D。"}, {"id": "yy-18286", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "岁末年初，急难险重任务面前，基层干部主动______最重的责任。", "options": ["抬起", "挑起", "扛起", "背起"], "answer": 2, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选C。"}, {"id": "yy-18287", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，红色资源是最生动的教材，科研人员让红色血脉代代相传。", "options": ["继续", "延续", "赓续", "接续"], "answer": 2, "explanation": "「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选C。"}, {"id": "yy-18288", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "入冬以来，金杯银杯不如老百姓的口碑，青年学子把每件小事都当大事办。", "options": ["建立", "创立", "树立", "设立"], "answer": 2, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选C。"}, {"id": "yy-18289", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "眼下，靠山吃山靠水吃水，程序员因地制宜______资源优势。", "options": ["发扬", "发挥", "发展", "施展"], "answer": 1, "explanation": "「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选B。"}, {"id": "yy-18290", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，老厂房变身文创园，渔民让工业遗存______新的活力。", "options": ["换发", "更新", "焕新", "焕发"], "answer": 3, "explanation": "「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选D。"}, {"id": "yy-18291", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "初秋时节，纪律规矩挺在前面，程序员始终______纪律底线。", "options": ["看守", "遵守", "把守", "严守"], "answer": 3, "explanation": "「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选D。"}, {"id": "yy-18292", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "岁末年初，把家国情怀融入课堂，茶农用身边故事打动学生。", "options": ["施肥", "浇灌", "培土", "厚植"], "answer": 3, "explanation": "「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选D。"}, {"id": "yy-18293", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "盛夏时节，营商环境就是生产力，设计师让企业成长有沃土。", "options": ["厚植", "培植", "培养", "培育"], "answer": 0, "explanation": "「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选A。"}, {"id": "yy-18294", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "一段时间以来，越是爬坡过坎，越要______必胜信心，文旅部门一步一个脚印向前走。", "options": ["坚决", "坚定", "坚持不懈", "坚强"], "answer": 1, "explanation": "「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选B。"}, {"id": "yy-18295", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "一段时间以来，靠山吃山靠水吃水，审计人员因地制宜______资源优势。", "options": ["施展", "发挥", "发展", "发扬"], "answer": 1, "explanation": "「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选B。"}, {"id": "yy-18296", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "入冬以来，二十年只做一件事，广大建设者在细分领域里做到极致。", "options": ["深掘", "深钻", "深挖", "深耕"], "answer": 3, "explanation": "「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选D。"}, {"id": "yy-18297", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "盛夏时节，跳出一时一地看发展，图书管理员着力______开放共赢的新格局。", "options": ["搭造", "架造", "构作", "构建"], "answer": 3, "explanation": "「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选D。"}, {"id": "yy-18298", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "这些年，乡情是最深的牵挂，非遗传承人以商会为平台______情感纽带。", "options": ["织牢", "捆牢", "系牢", "绑牢"], "answer": 0, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。"}, {"id": "yy-18299", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "初秋时节，老厂房变身文创园，快递员让工业遗存______新的活力。", "options": ["更新", "换发", "焕新", "焕发"], "answer": 3, "explanation": "「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选D。"}, {"id": "yy-18300", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "眼下，危难时刻冲得上去，教师的行动______了共产党员的担当。", "options": ["彰显", "暴露", "显露", "显摆"], "answer": 0, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选A。"}, {"id": "yy-18301", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "入冬以来，民生实事清单公示上墙，手工艺人一件一件______承诺。", "options": ["达成", "完成", "实现", "兑现"], "answer": 3, "explanation": "「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选D。"}, {"id": "yy-18302", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "一段时间以来，把家国情怀融入课堂，网格员用身边故事打动学生。", "options": ["浇灌", "培土", "施肥", "厚植"], "answer": 3, "explanation": "「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选D。"}, {"id": "yy-18303", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "开春以来，靠山吃山靠水吃水，青年学子因地制宜______资源优势。", "options": ["发挥", "发扬", "发展", "施展"], "answer": 0, "explanation": "「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选A。"}, {"id": "yy-18304", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "入冬以来，把消费潜力转化为增长实绩，设计师拿出了实招硬招。", "options": ["释放", "喷发", "发泄", "散发"], "answer": 0, "explanation": "「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选A。"}, {"id": "yy-18305", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "连日来，把家国情怀融入课堂，环卫工人用身边故事打动学生。", "options": ["浇灌", "厚植", "施肥", "培土"], "answer": 1, "explanation": "「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选B。"}, {"id": "yy-18306", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "岁末年初，让监督机制长出牙齿，治沙工人把制度笼子越扎越紧。", "options": ["修理", "修复", "健全", "修葺"], "answer": 2, "explanation": "「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选C。"}, {"id": "yy-18307", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "这些年，城乡公共服务仍有落差，审计人员以实策逐步______差距。", "options": ["缩小", "减小", "缩减", "减少"], "answer": 0, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选A。"}, {"id": "yy-18308", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "入冬以来，两岸同胞亲情割不断，快递员为青年交流______心灵心桥。", "options": ["架起", "垒砌", "修筑", "铺设"], "answer": 0, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选A。"}, {"id": "yy-18309", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，一揽子政策精准落地，税务干部着力______市场信心。", "options": ["鼓动", "提起", "提振", "振作"], "answer": 2, "explanation": "「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选C。"}, {"id": "yy-18310", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "盛夏时节，两岸同胞亲情割不断，博物馆讲解员为青年交流______心灵心桥。", "options": ["修筑", "架起", "铺设", "垒砌"], "answer": 1, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选B。"}, {"id": "yy-18311", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，急难险重任务面前，图书管理员主动______最重的责任。", "options": ["抬起", "挑起", "背起", "扛起"], "answer": 3, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。"}, {"id": "yy-18312", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "盛夏时节，老旧小区加装电梯、增设车位，税务干部尽力______居民多样需求。", "options": ["充足", "满足", "充盈", "满意"], "answer": 1, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选B。"}, {"id": "yy-18313", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "初秋时节，让监督机制长出牙齿，治沙工人把制度笼子越扎越紧。", "options": ["修葺", "修复", "健全", "修理"], "answer": 2, "explanation": "「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选C。"}, {"id": "yy-18314", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "这些年，城乡公共服务仍有落差，社区规划师以实策逐步______差距。", "options": ["减少", "缩小", "缩减", "减小"], "answer": 1, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选B。"}, {"id": "yy-18315", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "这些年，民生领域还有欠账，社区规划师列出清单逐项______短板。", "options": ["补丁", "贴补", "补齐", "修补"], "answer": 2, "explanation": "「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选C。"}, {"id": "yy-18316", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "近期，古城修缮不搞大拆大建，调解员让千年文脉在街巷间静静流淌。", "options": ["续接", "接通", "延续", "连接"], "answer": 2, "explanation": "「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选C。"}, {"id": "yy-18317", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "这些年，改革到了深水区，广大建设者以钉钉子精神______工作局面。", "options": ["掀开", "揭开", "打开", "翻开"], "answer": 2, "explanation": "「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选C。"}, {"id": "yy-18318", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "初秋时节，金融活水精准滴灌，治沙工人为小微企业______发展动力。", "options": ["灌输", "注入", "输入", "灌入"], "answer": 1, "explanation": "「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选B。"}, {"id": "yy-18319", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近年来，乡情是最深的牵挂，设计师以商会为平台______情感纽带。", "options": ["织牢", "系牢", "捆牢", "绑牢"], "answer": 0, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。"}, {"id": "yy-18320", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，让监督机制长出牙齿，工程师把制度笼子越扎越紧。", "options": ["修复", "健全", "修理", "修葺"], "answer": 1, "explanation": "「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选B。"}, {"id": "yy-18321", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "盛夏时节，让农产品出村进城，基层干部多方合力______销售通道。", "options": ["扩宽", "拓宽", "开辟", "开宽"], "answer": 1, "explanation": "「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选B。"}, {"id": "yy-18322", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "岁末年初，每一起案件都关乎群众对法治的信仰，审计人员用公正裁判______正义。", "options": ["护卫", "防御", "捍卫", "保卫"], "answer": 2, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选C。"}, {"id": "yy-18323", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "这些年，危难时刻冲得上去，非遗传承人的行动______了共产党员的担当。", "options": ["彰显", "显露", "显摆", "暴露"], "answer": 0, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选A。"}, {"id": "yy-18324", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "这些年，一年一度的民生大考结束，医护人员向群众______了温暖的答卷。", "options": ["递交", "上缴", "呈报", "交出"], "answer": 3, "explanation": "「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选D。"}, {"id": "yy-18325", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "岁末年初，让公共服务覆盖城乡，设计师持续______政策体系。", "options": ["补完", "完善", "修完", "完缮"], "answer": 1, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选B。"}, {"id": "yy-18326", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "盛夏时节，民生领域还有欠账，青年学子列出清单逐项______短板。", "options": ["补丁", "补齐", "修补", "贴补"], "answer": 1, "explanation": "「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选B。"}, {"id": "yy-18327", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "今年以来，订单排到明年，环卫工人发展的信心。", "options": ["倍受", "倍加", "倍增", "加倍"], "answer": 2, "explanation": "「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选C。"}, {"id": "yy-18328", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "开春以来，面对转型路上的重重难关，审计人员迎难而上，把一个个难关逐一______。", "options": ["化解", "攻克", "破除", "克服"], "answer": 1, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选B。"}, {"id": "yy-18329", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "一段时间以来，危难时刻冲得上去，基层干部的行动______了共产党员的担当。", "options": ["暴露", "彰显", "显摆", "显露"], "answer": 1, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选B。"}, {"id": "yy-18330", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "这些年，民生实事清单公示上墙，民警一件一件______承诺。", "options": ["兑现", "实现", "完成", "达成"], "answer": 0, "explanation": "「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选A。"}, {"id": "yy-18331", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "初秋时节，放宽准入激发创业热情，法官让创造活力。", "options": ["涌出", "淌出", "涌流", "流出"], "answer": 2, "explanation": "「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选C。"}, {"id": "yy-18332", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "近期，新区建设的宏伟蓝图已经展开，工程师正把一张张蓝图变成施工图。", "options": ["编织", "绘就", "修筑", "耕耘"], "answer": 1, "explanation": "「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选B。"}, {"id": "yy-18333", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，老厂房变身文创园，基层干部让工业遗存______新的活力。", "options": ["焕发", "焕新", "换发", "更新"], "answer": 0, "explanation": "「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选A。"}, {"id": "yy-18334", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近期，把消费潜力转化为增长实绩，网格员拿出了实招硬招。", "options": ["发泄", "释放", "散发", "喷发"], "answer": 1, "explanation": "「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选B。"}, {"id": "yy-18335", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "开春以来，改革红利持续显现，市场活力不断，果农信心更足。", "options": ["爆发", "突发", "暴发", "迸发"], "answer": 3, "explanation": "「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选D。"}, {"id": "yy-18336", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "入冬以来，让公共服务覆盖城乡，消防员持续______政策体系。", "options": ["修完", "补完", "完善", "完缮"], "answer": 2, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选C。"}, {"id": "yy-18337", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "开春以来，让农产品出村进城，程序员多方合力______销售通道。", "options": ["开宽", "开辟", "扩宽", "拓宽"], "answer": 3, "explanation": "「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选D。"}, {"id": "yy-18338", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "这些年，脱贫不是终点，图书管理员多措并举______脱贫成果。", "options": ["凝固", "加固", "稳固", "巩固"], "answer": 3, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选D。"}, {"id": "yy-18339", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "近期，越是众声喧哗，越需要______共识，志愿者们把大家的心拢到一起。", "options": ["冻住", "凝固", "凝结", "凝聚"], "answer": 3, "explanation": "「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选D。"}, {"id": "yy-18340", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，让公共服务覆盖城乡，环卫工人持续______政策体系。", "options": ["补完", "完缮", "完善", "修完"], "answer": 2, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选C。"}, {"id": "yy-18341", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，每一起案件都关乎群众对法治的信仰，科研人员用公正裁判______正义。", "options": ["捍卫", "护卫", "防御", "保卫"], "answer": 0, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选A。"}, {"id": "yy-18342", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "开春以来，减税降费政策落地，税务干部让企业真切感受到红利。", "options": ["散发", "发射", "释放", "发放"], "answer": 2, "explanation": "「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选C。"}, {"id": "yy-18343", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "今年以来，让监督机制长出牙齿，乡村医生把制度笼子越扎越紧。", "options": ["健全", "修复", "修理", "修葺"], "answer": 0, "explanation": "「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选A。"}, {"id": "yy-18344", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "初秋时节，春潮拍岸千帆竞，审计人员感受到创新活力。", "options": ["淌动", "流出", "涌出", "涌动"], "answer": 3, "explanation": "「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选D。"}, {"id": "yy-18345", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "这些年，把家国情怀融入课堂，茶农用身边故事打动学生。", "options": ["浇灌", "厚植", "培土", "施肥"], "answer": 1, "explanation": "「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选B。"}, {"id": "yy-18346", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "初秋时节，市场细胞活跃起来，铁路养护工让经济肌体活力。", "options": ["塞满", "填满", "装满", "充满"], "answer": 3, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选D。"}, {"id": "yy-18347", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，红色资源是最生动的教材，公交司机让红色血脉代代相传。", "options": ["延续", "接续", "继续", "赓续"], "answer": 3, "explanation": "「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选D。"}, {"id": "yy-18348", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近年来，把资源优势变成产业优势，税务干部下大气力______区域品牌。", "options": ["锻打", "打造", "打制", "拍打"], "answer": 1, "explanation": "「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选B。"}, {"id": "yy-18349", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "眼下，几十年如一日，驻村干部在平凡岗位上______着为民初心。", "options": ["保守", "坚守", "把守", "守卫"], "answer": 1, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选B。"}, {"id": "yy-18350", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "入冬以来，把消费潜力转化为增长实绩，青年学子拿出了实招硬招。", "options": ["发泄", "释放", "散发", "喷发"], "answer": 1, "explanation": "「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选B。"}, {"id": "yy-18351", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "初秋时节，改革到了深水区，护林员以钉钉子精神______工作局面。", "options": ["打开", "掀开", "翻开", "揭开"], "answer": 0, "explanation": "「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选A。"}, {"id": "yy-18352", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "开春以来，一次次说到做到，税务干部用行动______了群众的信任。", "options": ["换取", "获得", "博得", "赢得"], "answer": 3, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选D。"}, {"id": "yy-18353", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "近年来，卡脖子技术亟待攻坚，驻村干部集中力量______一个个瓶颈。", "options": ["突破", "捅破", "撞破", "冲破"], "answer": 0, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选A。"}, {"id": "yy-18354", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "入冬以来，改革到了深水区，调解员以钉钉子精神______工作局面。", "options": ["揭开", "翻开", "打开", "掀开"], "answer": 2, "explanation": "「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选C。"}, {"id": "yy-18355", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，脱贫不是终点，渔民多措并举______脱贫成果。", "options": ["巩固", "加固", "凝固", "稳固"], "answer": 0, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。"}, {"id": "yy-18356", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "入冬以来，越是众声喧哗，越需要______共识，社区工作者把大家的心拢到一起。", "options": ["凝结", "凝固", "冻住", "凝聚"], "answer": 3, "explanation": "「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选D。"}, {"id": "yy-18357", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "今年以来，卡脖子技术亟待攻坚，执法人员集中力量______一个个瓶颈。", "options": ["突破", "冲破", "撞破", "捅破"], "answer": 0, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选A。"}, {"id": "yy-18358", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "初秋时节，初心如磐，使命在肩，青年学子把承诺落到一件件小事上。", "options": ["践行", "执行", "履行", "旅行"], "answer": 0, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选A。"}, {"id": "yy-18359", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "连日来，老旧小区加装电梯、增设车位，设计师尽力______居民多样需求。", "options": ["满意", "满足", "充盈", "充足"], "answer": 1, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选B。"}, {"id": "yy-18360", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "岁末年初，安全底线不可逾越，驻村干部24小时轮班值守。", "options": ["把守", "镇守", "坚守", "看守"], "answer": 2, "explanation": "「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选C。"}, {"id": "yy-18361", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "入冬以来，从受理到反馈全流程留痕，青年学子以数字化手段______管理闭环。", "options": ["构建", "搭圈", "构画", "圈画"], "answer": 0, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选A。"}, {"id": "yy-18362", "module": "yanyu", "diff": 3, "exam": "医疗编", "prompt": "岁末年初，一揽子政策精准落地，青年学子着力______市场信心。", "options": ["振作", "提起", "鼓动", "提振"], "answer": 3, "explanation": "「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选D。"}, {"id": "yy-18363", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "连日来，放宽准入激发创业热情，乡村医生让创造活力。", "options": ["涌出", "涌流", "流出", "淌出"], "answer": 1, "explanation": "「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选B。"}, {"id": "yy-18364", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "近期，众人的事情由众人商量，农技人员把各方______到规划图上。", "options": ["凝聚", "归拢", "收拢", "聚拢"], "answer": 0, "explanation": "「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选A。"}, {"id": "yy-18365", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "今年以来，让要素流动更顺畅，就要______体制机制的藩篱。", "options": ["拆除", "捣毁", "铲平", "破除"], "answer": 3, "explanation": "「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选D。"}, {"id": "yy-18366", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "岁末年初，乡情是最深的牵挂，农技人员以商会为平台______情感纽带。", "options": ["织牢", "绑牢", "系牢", "捆牢"], "answer": 0, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。"}, {"id": "yy-18367", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "连日来，齐抓共管不是一句口号，农技人员推动齐抓共管合力。", "options": ["成形", "形成", "成型", "成立"], "answer": 1, "explanation": "「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选B。"}, {"id": "yy-18368", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "连日来，向存量要效益，广大建设者为产业升级______新空间。", "options": ["拓展", "拓开", "展开", "开展"], "answer": 0, "explanation": "「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选A。"}, {"id": "yy-18369", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，市场细胞活跃起来，公交司机让经济肌体活力。", "options": ["装满", "塞满", "充满", "填满"], "answer": 2, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选C。"}, {"id": "yy-18370", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，筑起生态安全屏障，税务干部让青山常在绿水长流。", "options": ["砌牢", "锁牢", "拴牢", "筑牢"], "answer": 3, "explanation": "「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选D。"}, {"id": "yy-18371", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "这些年，民生领域还有欠账，渔民列出清单逐项______短板。", "options": ["贴补", "补丁", "补齐", "修补"], "answer": 2, "explanation": "「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选C。"}, {"id": "yy-18372", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "开春以来，手握核心技术专利，手工艺人创新的底气。", "options": ["更足", "更壮", "更强", "更硬"], "answer": 0, "explanation": "「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选A。"}, {"id": "yy-18373", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "盛夏时节，小哨兵大作用，电力工人让基层网格______更大作用。", "options": ["发挥", "施展", "表现", "发扬"], "answer": 0, "explanation": "「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选A。"}, {"id": "yy-18374", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "盛夏时节，邻里纠纷无小事，科研人员用真心______一件件矛盾。", "options": ["解开", "瓦解", "消融", "化解"], "answer": 3, "explanation": "「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选D。"}, {"id": "yy-18375", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "岁末年初，停车难是城市治理的老大难，果农用共享思维______了这一难题。", "options": ["解开", "解冻", "解释", "破解"], "answer": 3, "explanation": "「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选D。"}, {"id": "yy-18376", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "这些年，面对转型路上的重重难关，医护人员迎难而上，把一个个难关逐一______。", "options": ["破除", "克服", "化解", "攻克"], "answer": 3, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。"}, {"id": "yy-18377", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "开春以来，传统村落保护性开发，消防员既富了口袋，也______了乡愁。", "options": ["留住", "截留", "拘留", "扣留"], "answer": 0, "explanation": "「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选A。"}, {"id": "yy-18378", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "近期，让公共服务覆盖城乡，设计师持续______政策体系。", "options": ["补完", "完缮", "修完", "完善"], "answer": 3, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选D。"}, {"id": "yy-18379", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "初秋时节，众人的事情由众人商量，非遗传承人把各方______到规划图上。", "options": ["凝聚", "归拢", "收拢", "聚拢"], "answer": 0, "explanation": "「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选A。"}, {"id": "yy-18380", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "这些年，初心如磐，使命在肩，网格员把承诺落到一件件小事上。", "options": ["执行", "履行", "旅行", "践行"], "answer": 3, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选D。"}, {"id": "yy-18381", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "岁末年初，红色资源是最生动的教材，图书管理员让红色血脉代代相传。", "options": ["延续", "接续", "赓续", "继续"], "answer": 2, "explanation": "「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选C。"}, {"id": "yy-18382", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近期，卡脖子技术亟待攻坚，消防员集中力量______一个个瓶颈。", "options": ["捅破", "突破", "撞破", "冲破"], "answer": 1, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选B。"}, {"id": "yy-18383", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "盛夏时节，一揽子政策精准落地，工程师着力______市场信心。", "options": ["提振", "鼓动", "振作", "提起"], "answer": 0, "explanation": "「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选A。"}, {"id": "yy-18384", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "近年来，景区客流高峰来临，果农全员上岗______游览秩序。", "options": ["保护", "护卫", "维持", "维护"], "answer": 3, "explanation": "「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选D。"}, {"id": "yy-18385", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近期，新区建设的宏伟蓝图已经展开，设计师正把一张张蓝图变成施工图。", "options": ["绘就", "编织", "耕耘", "修筑"], "answer": 0, "explanation": "「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选A。"}, {"id": "yy-18386", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "近年来，金融活水精准滴灌，非遗传承人为小微企业______发展动力。", "options": ["注入", "灌输", "输入", "灌入"], "answer": 0, "explanation": "「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选A。"}, {"id": "yy-18387", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "开春以来，让新业态释放新动能，设计师在制度创新上先行先试。", "options": ["引爆", "激发", "点燃", "发动"], "answer": 1, "explanation": "「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选B。"}, {"id": "yy-18388", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "盛夏时节，初心如磐，使命在肩，调解员把承诺落到一件件小事上。", "options": ["执行", "履行", "践行", "旅行"], "answer": 2, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选C。"}, {"id": "yy-18389", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "岁末年初，把监督防线扎到最基层，博物馆讲解员走村入户听民声。", "options": ["织厚", "织密", "缝密", "织补"], "answer": 1, "explanation": "「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选B。"}, {"id": "yy-18390", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "岁末年初，让农产品出村进城，消防员多方合力______销售通道。", "options": ["开辟", "拓宽", "扩宽", "开宽"], "answer": 1, "explanation": "「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选B。"}, {"id": "yy-18391", "module": "yanyu", "diff": 3, "exam": "医疗编", "prompt": "近年来，新区建设的宏伟蓝图已经展开，公交司机正把一张张蓝图变成施工图。", "options": ["绘就", "耕耘", "编织", "修筑"], "answer": 0, "explanation": "「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选A。"}, {"id": "yy-18392", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "这些年，被动状态必须改变，驻村干部用硬措施______了不利局面。", "options": ["回转", "反转", "倒转", "扭转"], "answer": 3, "explanation": "「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选D。"}, {"id": "yy-18393", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "盛夏时节，万丈高楼平地起，工程师一锤一钎______发展基础。", "options": ["踩实", "填实", "夯实", "砸实"], "answer": 2, "explanation": "「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选C。"}, {"id": "yy-18394", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "岁末年初，老工业基地涅槃重生，手工艺人加快新旧动能步伐。", "options": ["转变", "转换", "变换", "改换"], "answer": 1, "explanation": "「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选B。"}, {"id": "yy-18395", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "开春以来，营商环境就是生产力，执法人员让企业成长有沃土。", "options": ["培养", "厚植", "培育", "培植"], "answer": 1, "explanation": "「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选B。"}, {"id": "yy-18396", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "眼下，每一起案件都关乎群众对法治的信仰，环卫工人用公正裁判______正义。", "options": ["防御", "护卫", "保卫", "捍卫"], "answer": 3, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选D。"}, {"id": "yy-18397", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "初秋时节，景区客流高峰来临，手工艺人全员上岗______游览秩序。", "options": ["护卫", "保护", "维护", "维持"], "answer": 2, "explanation": "「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选C。"}, {"id": "yy-18398", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，汛期将至，消防员对辖区地质灾害隐患逐点______。", "options": ["排查", "普查", "检查", "检察"], "answer": 0, "explanation": "「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选A。"}, {"id": "yy-18399", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "开春以来，几十年如一日，茶农在平凡岗位上______着为民初心。", "options": ["坚守", "守卫", "保守", "把守"], "answer": 0, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选A。"}, {"id": "yy-18400", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "近期，老厂房变身文创园，快递员让工业遗存______新的活力。", "options": ["焕发", "焕新", "更新", "换发"], "answer": 0, "explanation": "「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选A。"}, {"id": "yy-18401", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "今年以来，放宽准入激发创业热情，果农让创造活力。", "options": ["涌出", "流出", "涌流", "淌出"], "answer": 2, "explanation": "「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选C。"}, {"id": "yy-18402", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "连日来，改革到了深水区，科研人员以钉钉子精神______工作局面。", "options": ["翻开", "打开", "揭开", "掀开"], "answer": 1, "explanation": "「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选B。"}, {"id": "yy-18403", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "初秋时节，急难险重任务面前，社区规划师主动______最重的责任。", "options": ["背起", "抬起", "挑起", "扛起"], "answer": 3, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。"}, {"id": "yy-18404", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "近期，一二三产融合发展，渔民推动产业链不断延伸。", "options": ["伸长", "延长", "拉长", "延伸"], "answer": 3, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。"}, {"id": "yy-18405", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "眼下，民生实事清单公示上墙，消防员一件一件______承诺。", "options": ["实现", "兑现", "达成", "完成"], "answer": 1, "explanation": "「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选B。"}, {"id": "yy-18406", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，危难时刻冲得上去，设计师的行动______了共产党员的担当。", "options": ["显露", "彰显", "暴露", "显摆"], "answer": 1, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选B。"}, {"id": "yy-18407", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "开春以来，誓师大会上，乡村医生精神斗志，誓言响彻训练场。", "options": ["高昂", "高扬", "昂扬", "高涨"], "answer": 2, "explanation": "「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选C。"}, {"id": "yy-18408", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "这些年，让新业态释放新动能，文旅部门在制度创新上先行先试。", "options": ["发动", "引爆", "点燃", "激发"], "answer": 3, "explanation": "「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选D。"}, {"id": "yy-18409", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "岁末年初，让监督机制长出牙齿，农技人员把制度笼子越扎越紧。", "options": ["健全", "修葺", "修理", "修复"], "answer": 0, "explanation": "「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选A。"}, {"id": "yy-18410", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "这些年，金杯银杯不如老百姓的口碑，工程师把每件小事都当大事办。", "options": ["树立", "建立", "创立", "设立"], "answer": 0, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选A。"}, {"id": "yy-18411", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "今年以来，从受理到反馈全流程留痕，医护人员以数字化手段______管理闭环。", "options": ["搭圈", "构画", "圈画", "构建"], "answer": 3, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选D。"}, {"id": "yy-18412", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，一次次说到做到，快递员用行动______了群众的信任。", "options": ["赢得", "换取", "博得", "获得"], "answer": 0, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选A。"}, {"id": "yy-18413", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "初秋时节，发展为了人民，非遗传承人把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增加", "增进", "增殖", "增添"], "answer": 1, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选B。"}, {"id": "yy-18414", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "开春以来，老旧小区加装电梯、增设车位，社区工作者尽力______居民多样需求。", "options": ["满足", "充盈", "满意", "充足"], "answer": 0, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选A。"}, {"id": "yy-18415", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "入冬以来，绿水青山就是金山银山，志愿者们代代接力______绿色生态。", "options": ["守望", "看守", "守候", "守护"], "answer": 3, "explanation": "「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选D。"}, {"id": "yy-18416", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "入冬以来，每一起案件都关乎群众对法治的信仰，环卫工人用公正裁判______正义。", "options": ["捍卫", "护卫", "保卫", "防御"], "answer": 0, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选A。"}, {"id": "yy-18417", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "开春以来，城乡公共服务仍有落差，市场监管部门以实策逐步______差距。", "options": ["减少", "减小", "缩减", "缩小"], "answer": 3, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选D。"}, {"id": "yy-18418", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "盛夏时节，停车难是城市治理的老大难，执法人员用共享思维______了这一难题。", "options": ["解释", "解开", "破解", "解冻"], "answer": 2, "explanation": "「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选C。"}, {"id": "yy-18419", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "开春以来，誓师大会上，审计人员精神斗志，誓言响彻训练场。", "options": ["高昂", "高扬", "高涨", "昂扬"], "answer": 3, "explanation": "「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选D。"}, {"id": "yy-18420", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "这些年，向存量要效益，非遗传承人为产业升级______新空间。", "options": ["展开", "开展", "拓展", "拓开"], "answer": 2, "explanation": "「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选C。"}]);